window.CGDD_DATA = {"flow":"%% The_Last_Light script flow\n%% Generated by CGDD/Export Trace Docs. Do not edit by hand.\nflowchart TD\n  Billboard(\"<b>Billboard</b><br/>Rotates a world-space label to face the camera (yaw only).\")\n  BreakerSwitch(\"<b>BreakerSwitch</b><br/>Room 3 — one small up/down breaker toggle, no feedback on correctness.\")\n  CardAlignmentUI(\"<b>CardAlignmentUI</b><br/>Room 2 — rotate-to-align calibration card puzzle, reveals the exit code digits.\")\n  CardReader(\"<b>CardReader</b><br/>Room 2 — unlocks the sample cabinet with the access card.\")\n  CeilingCardPanel(\"<b>CeilingCardPanel</b><br/>Room 2 L5 panel — reach-gated access card pickup (foot height + proximity, not raycast).\")\n  ClueMarker(\"<b>ClueMarker</b><br/>Passive Room 1 clue label — counts as seen just by being looked at.\")\n  ClueTracker(\"<b>ClueTracker</b><br/>Bottom-left HUD — fills in each Room 1 clue digit as the player discovers it.\")\n  CodeManager(\"<b>CodeManager</b><br/>Room 1's 4-digit code source — reads GameState, validates keypad guesses.\")\n  DataMatrixScreen(\"<b>DataMatrixScreen</b><br/>Room 2 matrix screen — opens the alignment UI once the calibration card is in hand.\")\n  DoorwayStoolBlock(\"<b>DoorwayStoolBlock</b><br/>Room 2 — blocks/warns the player from carrying the stool out through a doorway.\")\n  DrawerClue(\"<b>DrawerClue</b><br/>Room 1 Clue 2 setup (Triangle) — opens the drawer, reveals the paper inside.\")\n  EndMenu(\"<b>EndMenu</b><br/>Win/loss screen — Retry Room (keep progress) or Play Again (fresh game).\")\n  FirstPersonController(\"<b>FirstPersonController</b><br/>Player movement + mouse look; exposes SetInputEnabled() so UI overlays can pause it.\")\n  GameState(\"<b>GameState</b><br/>Static cross-scene game state — per-room codes, solved rooms, checkpoints, win/loss.\")\n  GrazingLightReveal(\"<b>GrazingLightReveal</b><br/>Reveals a surface only under a close, shallow-angle light graze (Room 3's nameplate).\")\n  ImmediateRoomEntry(\"<b>ImmediateRoomEntry</b><br/>Room 1's 'already inside at spawn' substitute for RoomEntryTrigger.\")\n  InspectionLamp(\"<b>InspectionLamp</b><br/>Room 3+ handheld spotlight, toggled with F — follows wherever the player looks.\")\n  InspectionLampCradle(\"<b>InspectionLampCradle</b><br/>Room 3 — assembles the inspection lamp from two carried parts.\")\n  Inventory(\"<b>Inventory</b><br/>Bottom-center held-item row (max 4) — puzzle objects auto-use whatever item they need.\")\n  InventoryPickup(\"<b>InventoryPickup</b><br/>Generic world pickup — E adds it to the inventory and hides it.\")\n  KeypadController(\"<b>KeypadController</b><br/>World-space keypad prop — E opens its KeypadUI panel.\")\n  KeypadDigitButton(\"<b>KeypadDigitButton</b><br/>UI button wrapper — forwards a digit press to its KeypadUI.\")\n  KeypadUI(\"<b>KeypadUI</b><br/>Shared exit keypad (Room 1 + Room 2) — checks a guess, slides the door open.\")\n  LightSwitchClue(\"<b>LightSwitchClue</b><br/>Room 1 Clue 4 (Bar) — toggles a light; the clue text is only readable while it's off.\")\n  MainBreaker(\"<b>MainBreaker</b><br/>Room 3 — checks all 4 breakers against the nameplate pattern, opens the door or penalizes.\")\n  MovableCabinetClue(\"<b>MovableCabinetClue</b><br/>Room 1 Clue 1 (Circle) — slides the displaced cabinet back, reveals hidden wall text.\")\n  NameplateArrows(\"<b>NameplateArrows</b><br/>Fills Room 3's nameplate arrows from the random breaker target pattern.\")\n  ObjectiveToast(\"<b>ObjectiveToast</b><br/>Top-center fade-in room objective line; Tab replays it.\")\n  PaperCloseupClue(\"<b>PaperCloseupClue</b><br/>Room 1 Clue 2 (Triangle) — opens the paper close-up, marks the clue seen.\")\n  PaperCloseupUI(\"<b>PaperCloseupUI</b><br/>Full-screen paper-reading overlay for Room 1's Triangle clue.\")\n  PlayerInteractor(\"<b>PlayerInteractor</b><br/>Raycasts for interactables each frame and routes E / Tab / F input to them.\")\n  Room2CodeValidator(\"<b>Room2CodeValidator</b><br/>Room 2's exit-code check against GameState.\")\n  RoomEntryTrigger(\"<b>RoomEntryTrigger</b><br/>First-entry doorway trigger — starts the room timer, sets the save checkpoint, shows the objective toast.\")\n  RoomExitTrigger(\"<b>RoomExitTrigger</b><br/>Marks a room solved on exit; the final one ends the game in victory.\")\n  RoomTimer(\"<b>RoomTimer</b><br/>Per-room silent countdown — flicker, sequential light shutoff, blackout loss.\")\n  SlideMover(\"<b>SlideMover</b><br/>Generic smooth local-position slide, reused by doors/drawers/cabinets.\")\n  StoolCarrier(\"<b>StoolCarrier</b><br/>Room 2 — carries/places the stool with a ghost placement preview.\")\n  StoolPickupTarget(\"<b>StoolPickupTarget</b><br/>Room 2 stool's pickup trigger.\")\n  TitleMenu(\"<b>TitleMenu</b><br/>Title screen — Start begins a brand-new game.\")\n  IKeypadValidator(\"<b>IKeypadValidator</b><br/>script missing\")\n\n  CardAlignmentUI --> GameState\n  CardAlignmentUI --> Inventory\n  CardReader --> Inventory\n  CardReader --> SlideMover\n  CeilingCardPanel --> FirstPersonController\n  CeilingCardPanel --> Inventory\n  ClueMarker --> CodeManager\n  ClueTracker --> GameState\n  CodeManager --> GameState\n  DataMatrixScreen --> CardAlignmentUI\n  DataMatrixScreen --> Inventory\n  DoorwayStoolBlock --> StoolCarrier\n  DrawerClue --> SlideMover\n  EndMenu --> GameState\n  GrazingLightReveal --> InspectionLamp\n  ImmediateRoomEntry --> GameState\n  ImmediateRoomEntry --> RoomTimer\n  ImmediateRoomEntry --> ObjectiveToast\n  ImmediateRoomEntry --> Inventory\n  InspectionLampCradle --> Inventory\n  InspectionLampCradle --> InspectionLamp\n  InventoryPickup --> Inventory\n  KeypadController --> KeypadUI\n  KeypadDigitButton --> KeypadUI\n  KeypadUI --> IKeypadValidator\n  KeypadUI --> ClueTracker\n  KeypadUI --> RoomTimer\n  KeypadUI --> SlideMover\n  KeypadUI --> GameState\n  LightSwitchClue --> CodeManager\n  MainBreaker --> GameState\n  MainBreaker --> RoomTimer\n  MainBreaker --> SlideMover\n  MovableCabinetClue --> SlideMover\n  NameplateArrows --> GameState\n  PaperCloseupClue --> PaperCloseupUI\n  PaperCloseupClue --> CodeManager\n  PaperCloseupClue --> ClueTracker\n  PaperCloseupUI --> FirstPersonController\n  PlayerInteractor --> ClueTracker\n  PlayerInteractor --> StoolCarrier\n  PlayerInteractor --> ObjectiveToast\n  PlayerInteractor --> InspectionLamp\n  Room2CodeValidator --> GameState\n  RoomEntryTrigger --> GameState\n  RoomEntryTrigger --> RoomTimer\n  RoomEntryTrigger --> ObjectiveToast\n  RoomEntryTrigger --> Inventory\n  RoomExitTrigger --> GameState\n  RoomTimer --> GameState\n  RoomTimer --> LightSwitchClue\n  StoolCarrier --> FirstPersonController\n  StoolPickupTarget --> StoolCarrier\n  TitleMenu --> GameState\n\n  classDef manager fill:#f0a202,stroke:#1a140e,color:#1a140e,stroke-width:2.5px\n  classDef actor fill:#fff8ea,stroke:#1a140e,color:#1a140e,stroke-width:2px\n  classDef world fill:#9cba6a,stroke:#1a140e,color:#1a140e,stroke-width:2px\n  classDef ui fill:#efe6cf,stroke:#c4841a,color:#1a140e,stroke-width:2px\n  classDef other fill:#efe6cf,stroke:#1a140e,color:#1a140e,stroke-width:2px\n  class CodeManager,FirstPersonController,KeypadController manager\n  class PlayerInteractor actor\n  class CardAlignmentUI,EndMenu,KeypadUI,PaperCloseupUI,TitleMenu ui\n  class Billboard,BreakerSwitch,CardReader,CeilingCardPanel,ClueMarker,ClueTracker,DataMatrixScreen,DoorwayStoolBlock,DrawerClue,GameState,GrazingLightReveal,ImmediateRoomEntry,InspectionLamp,InspectionLampCradle,Inventory,InventoryPickup,KeypadDigitButton,LightSwitchClue,MainBreaker,MovableCabinetClue,NameplateArrows,ObjectiveToast,PaperCloseupClue,Room2CodeValidator,RoomEntryTrigger,RoomExitTrigger,RoomTimer,SlideMover,StoolCarrier,StoolPickupTarget,IKeypadValidator other\n","tunables":"# Tunables\n\nGenerated from `@tune` headers by the menu `CGDD/Export Trace Docs`. Hand edits are overwritten on the next export.\n\n| Script | Field | Type | Range | Default | Note |\n| --- | --- | --- | --- | --- | --- |\n| CardAlignmentUI | startRotationSteps | int | 1-3 | 1 | 90-degree steps away from aligned at start |\n| CardReader | slideDuration | float | 0.3-2 | 0.8 | cabinet door slide time (s) |\n| CeilingCardPanel | minFootHeight | float | 0.2-1 | 0.4 | required standing height (m) |\n| CeilingCardPanel | maxHorizontalDistance | float | 0.5-2 | 1 | required proximity to L5 (m) |\n| DrawerClue | slideDuration | float | 0.2-1.5 | 0.6 | drawer slide time (s) |\n| FirstPersonController | moveSpeed | float | 1-8 | 3.5 | walking speed (m/s) |\n| FirstPersonController | mouseSensitivity | float | 0.05-0.5 | 0.12 | look sensitivity |\n| GrazingLightReveal | maxDistance | float | 0.5-3 | 1.5 | required lamp distance (m) |\n| GrazingLightReveal | maxGrazeAngle | float | 10-45 | 30 | allowed angle from parallel-to-surface (deg) |\n| KeypadUI | doorSlideDuration | float | 0.5-2 | 1 | door open animation time |\n| KeypadUI | wrongGuessPenalty | float | 0-30 | 0 | seconds lost per wrong code |\n| LightSwitchClue | fadeDuration | float | 0.2-1 | 0.5 | light/text fade time (s) |\n| MainBreaker | wrongPenalty | float | 0-30 | 15 | seconds lost per wrong submit |\n| MovableCabinetClue | slideDuration | float | 0.3-2 | 1 | cabinet slide time (s) |\n| ObjectiveToast | holdDuration | float | 2-10 | 5 | how long the toast stays fully visible (s) |\n| PlayerInteractor | range | float | 1-4 | 2 | interaction raycast distance (m) |\n| RoomTimer | totalDuration | float | 60-400 | 180 | room time limit (s) |\n| RoomTimer | flickerWindow | float | 20-90 | 60 | seconds remaining when flicker starts |\n| RoomTimer | shutoffWindow | float | 5-40 | 20 | seconds remaining when sequential shutoff starts |\n| RoomTimer | blackoutHold | float | 1-5 | 2 | blackout hold before loss (s) |\n| RoomTimer | penaltyFlashDuration | float | 0.1-1 | 0.3 | penalty dim-flash length (s) |\n| StoolCarrier | maxPlaceDistance | float | 1-4 | 2 | how far from the player the stool can be placed (m) |\n\n","challenge":"# How the challenge changes\n\nLook first at whether win and loss change, then at whether the player's verb changes. If neither changes, it is the same game, just tighter or looser.\n\n| Change | Win/loss changed | Verb changed | Data | Script.field |\n| --- | --- | --- | --- | --- |\n| Start: (describe baseline feel) | — (baseline) | — (player verb) | field=default | ScriptName.field |\n","devlog":"# DEVLOG\n\nOnly append. Do not edit old sections. Two samples stay so students can see the format.\n\nOnly changes to the game itself are logged: the verb, win and loss, pressure, and what the player can feel.\nSite language, diagram styling, and click-to-read-script do not go into an Interaction or a Stage Reflection.\n\nEach gameplay change should add a section `## Interaction NNN — title` (the Agent can append this when it changes the game).\nAdd `## Stage Reflection NNN — title` only when you ask for one: Keep / Change / Cut, and which AI suggestions you accepted or rejected. That reflection stays on the game.\n\n## Interaction 000 — EXAMPLE (sample, do not delete)\n\n- Date: —\n- Who asked: teacher (sample)\n- Request: Tighten one tunable and see if it is still the same game.\n- What changed: Sample only. The current code was not changed. A real change would touch only one `@tune` field.\n- Result: The player's verb did not change. Win and loss did not change. Pressure changed, not the skeleton.\n\n## Stage Reflection 000 — EXAMPLE (sample, do not delete)\n\n### Keep\n- A core verb you can say in one sentence, and a clear win/loss.\n\n### Change\n- To make it harder, turn an existing `@tune` first. Do not add a new system yet.\n\n### Cut\n- No shop, no deep inventory, no optimization that is off-lesson.\n\n### AI\n- Accept: tune feel with existing fields; avoid opening new scripts.\n- Reject: GraphView, object pools, long hand-written scene YAML. This class is about script relationships and tunable numbers.\n","scripts":{"Billboard":{"path":"Assets/Scripts/Gameplay/Billboard.cs","role":"Rotates a world-space label to face the camera (yaw only).","source":"// @role Rotates a world-space label to face the camera (yaw only).\n\nusing UnityEngine;\n\n/// Rotates a world-space clue label to always face the camera (yaw only), so it reads correctly\n/// from any approach angle instead of only from one specific direction. This does not defeat\n/// occlusion-based hide/reveal puzzles (e.g. the pillar clue): whether the label is visible at\n/// all still depends purely on its fixed world position relative to whatever solid geometry\n/// might be blocking it, not on which way it's currently facing.\npublic class Billboard : MonoBehaviour\n{\n    Transform _cam;\n\n    void LateUpdate()\n    {\n        if (_cam == null)\n        {\n            if (Camera.main == null) return;\n            _cam = Camera.main.transform;\n        }\n\n        Vector3 dir = transform.position - _cam.position;\n        dir.y = 0f;\n        if (dir.sqrMagnitude < 0.0001f) return;\n        transform.rotation = Quaternion.LookRotation(dir.normalized, Vector3.up);\n    }\n}\n"},"BreakerSwitch":{"path":"Assets/Scripts/Gameplay/BreakerSwitch.cs","role":"Room 3 — one small up/down breaker toggle, no feedback on correctness.","source":"// @role Room 3 — one small up/down breaker toggle, no feedback on correctness.\n\nusing UnityEngine;\n\n/// One of the 4 small breakers: E flips it between up and down, no other feedback (per spec — the\n/// player has to read the nameplate's arrows, not watch for a hint here).\npublic class BreakerSwitch : MonoBehaviour, IInteractable\n{\n    public Transform leverVisual;\n    public Vector3 downEuler = new Vector3(20f, 0, 0);\n    public Vector3 upEuler = new Vector3(-20f, 0, 0);\n\n    public bool IsUp { get; private set; }\n\n    public string InteractionPrompt => \"Flip breaker\";\n    public bool CanInteract => true;\n    public string BlockedReason => null;\n\n    public void Interact(GameObject interactor) => SetUp(!IsUp);\n\n    public void SetUp(bool up)\n    {\n        IsUp = up;\n        if (leverVisual != null) leverVisual.localRotation = Quaternion.Euler(up ? upEuler : downEuler);\n    }\n}\n"},"CardAlignmentUI":{"path":"Assets/Scripts/Gameplay/CardAlignmentUI.cs","role":"Room 2 — rotate-to-align calibration card puzzle, reveals the exit code digits.","source":"// @role Room 2 — rotate-to-align calibration card puzzle, reveals the exit code digits.\n// @calls GameState, Inventory\n// @tune startRotationSteps:int:1-3:90-degree steps away from aligned at start\n\nusing System.Collections;\nusing UnityEngine;\nusing UnityEngine.InputSystem;\nusing TMPro;\n\n/// Full-screen overlay for Room 2's calibration card: a 4x4 digit grid, fully hidden until the\n/// overlaid card is rotated (R, 90 degrees per press) to the one orientation where its notch\n/// lines up with the frame's, then pressed on (E). A correct press reveals the 4 \"hole\" cells\n/// (the rest stay hidden — there's no card model to visually cover them, so \"hidden\" stands in for\n/// \"covered by the card\"); a wrong one bounces/rejects with no digits shown. Once solved the\n/// alignment is remembered, so reopening the panel just shows the already-revealed result\n/// (\"退出界面后卡片留在屏幕上\") instead of making the player redo the rotation.\npublic class CardAlignmentUI : MonoBehaviour\n{\n    public static CardAlignmentUI Instance { get; private set; }\n\n    public GameObject panelRoot;\n    public TMP_Text[] matrixCells = new TMP_Text[16]; // row-major, row*4+col\n    public RectTransform cardRect;\n    public TMP_Text statusText;\n\n    [Tooltip(\"Which of the 16 cells each of the 4 holes sits over, in pinhole-number order (1-4).\")]\n    public int[] holeCellIndex = new int[4];\n    [Tooltip(\"0-3: how many 90-degree steps away from aligned the card starts.\")]\n    public int startRotationSteps = 1;\n\n    public bool Aligned { get; private set; }\n    public bool IsOpen => panelRoot != null && panelRoot.activeSelf;\n\n    int _rotationSteps;\n    bool _busy;\n\n    void Awake()\n    {\n        Instance = this;\n        panelRoot.SetActive(false);\n        PopulateMatrix();\n    }\n\n    /// The matrix's actual digits only mean anything once a real game is in progress\n    /// (GameState.Room2Code), so they're filled in here at runtime rather than baked in by the\n    /// editor generator — Room2GameplayBuilder only lays out 16 empty cells. All 16 start hidden\n    /// (standing in for \"covered by the card\"); RevealHoles() only ever un-hides the 4 hole cells.\n    void PopulateMatrix()\n    {\n        GameState.EnsureStarted();\n        var holeSet = new System.Collections.Generic.HashSet<int>(holeCellIndex);\n        for (int i = 0; i < matrixCells.Length; i++)\n        {\n            if (matrixCells[i] == null) continue;\n            int digit = holeSet.Contains(i) ? GameState.Room2Code[System.Array.IndexOf(holeCellIndex, i)] : Random.Range(0, 10);\n            matrixCells[i].text = digit.ToString();\n            matrixCells[i].gameObject.SetActive(false);\n        }\n    }\n\n    public void Open()\n    {\n        if (IsOpen) return;\n        panelRoot.SetActive(true);\n        _rotationSteps = Aligned ? 0 : startRotationSteps;\n        ApplyRotationVisual();\n        FirstPersonController.Instance.SetInputEnabled(false);\n    }\n\n    public void Close()\n    {\n        panelRoot.SetActive(false);\n        FirstPersonController.Instance.SetInputEnabled(true);\n    }\n\n    public void Rotate()\n    {\n        if (Aligned || _busy) return;\n        _rotationSteps = (_rotationSteps + 1) % 4;\n        ApplyRotationVisual();\n    }\n\n    public void TryAttach()\n    {\n        if (Aligned || _busy) return;\n\n        if (_rotationSteps == 0)\n        {\n            Aligned = true;\n            RevealHoles();\n            if (Inventory.Instance != null) Inventory.Instance.Remove(\"CalibrationCard\");\n            if (statusText != null) statusText.text = \"Aligned.\";\n        }\n        else\n        {\n            StartCoroutine(RejectBounce());\n        }\n    }\n\n    void RevealHoles()\n    {\n        for (int i = 0; i < holeCellIndex.Length; i++)\n        {\n            int cell = holeCellIndex[i];\n            if (cell >= 0 && cell < matrixCells.Length && matrixCells[cell] != null)\n                matrixCells[cell].gameObject.SetActive(true);\n        }\n    }\n\n    void ApplyRotationVisual()\n    {\n        if (cardRect != null) cardRect.localRotation = Quaternion.Euler(0, 0, -90f * _rotationSteps);\n        if (statusText != null) statusText.text = \"\";\n    }\n\n    IEnumerator RejectBounce()\n    {\n        _busy = true;\n        if (statusText != null) statusText.text = \"Notch not aligned.\";\n        if (cardRect != null)\n        {\n            Vector3 basePos = cardRect.anchoredPosition3D;\n            float t = 0f, duration = 0.25f, magnitude = 14f;\n            while (t < duration)\n            {\n                t += Time.deltaTime;\n                float k = Mathf.Sin(t / duration * Mathf.PI);\n                cardRect.anchoredPosition3D = basePos + new Vector3(0, -k * magnitude, 0);\n                yield return null;\n            }\n            cardRect.anchoredPosition3D = basePos;\n        }\n        _busy = false;\n    }\n\n    void Update()\n    {\n        if (!IsOpen || Keyboard.current == null) return;\n        if (Keyboard.current.escapeKey.wasPressedThisFrame) { Close(); return; }\n        if (Keyboard.current.eKey.wasPressedThisFrame) TryAttach();\n        if (Keyboard.current.rKey.wasPressedThisFrame) Rotate();\n    }\n}\n"},"CardReader":{"path":"Assets/Scripts/Gameplay/CardReader.cs","role":"Room 2 — unlocks the sample cabinet with the access card.","source":"// @role Room 2 — unlocks the sample cabinet with the access card.\n// @calls Inventory, SlideMover\n// @tune slideDuration:float:0.3-2:cabinet door slide time (s)\n\nusing System.Collections;\nusing UnityEngine;\n\n/// Mounted on the sample cabinet. E with the access card in hand: consumes it, flips the\n/// indicator green, slides the cabinet door open. E without it: red flash + \"Access denied\",\n/// nothing consumed, cabinet stays locked.\npublic class CardReader : MonoBehaviour, IInteractable\n{\n    public string requiredItemId = \"AccessCard\";\n    public SlideMover cabinetDoor;\n    public Vector3 cabinetOpenLocalPosition;\n    public float slideDuration = 0.8f;\n    public Renderer indicatorRenderer;\n    public Color deniedColor = new Color(0.9f, 0.15f, 0.1f);\n    public Color grantedColor = new Color(0.2f, 0.85f, 0.3f);\n    [Tooltip(\"Revealed (SetActive(true)) once the cabinet unlocks, e.g. the calibration card sitting inside.\")]\n    public GameObject revealOnUnlock;\n\n    bool _unlocked;\n\n    public string InteractionPrompt => _unlocked ? null : \"Scan card\";\n    public bool CanInteract => !_unlocked;\n    public string BlockedReason => null;\n\n    void Start()\n    {\n        if (indicatorRenderer != null) indicatorRenderer.material.color = deniedColor;\n    }\n\n    public void Interact(GameObject interactor)\n    {\n        if (_unlocked) return;\n\n        if (Inventory.Instance != null && Inventory.Instance.HasItem(requiredItemId))\n        {\n            _unlocked = true;\n            Inventory.Instance.Remove(requiredItemId);\n            if (indicatorRenderer != null) indicatorRenderer.material.color = grantedColor;\n            cabinetDoor.SlideTo(cabinetOpenLocalPosition, slideDuration);\n            if (revealOnUnlock != null) revealOnUnlock.SetActive(true);\n        }\n        else\n        {\n            if (Inventory.Instance != null) Inventory.Instance.ShowMessage(\"Access denied\");\n            StartCoroutine(DenyFlash());\n        }\n    }\n\n    IEnumerator DenyFlash()\n    {\n        if (indicatorRenderer == null) yield break;\n        for (int i = 0; i < 3; i++)\n        {\n            indicatorRenderer.material.color = Color.black;\n            yield return new WaitForSeconds(0.1f);\n            indicatorRenderer.material.color = deniedColor;\n            yield return new WaitForSeconds(0.1f);\n        }\n    }\n}\n"},"CeilingCardPanel":{"path":"Assets/Scripts/Gameplay/CeilingCardPanel.cs","role":"Room 2 L5 panel — reach-gated access card pickup (foot height + proximity, not raycast).","source":"// @role Room 2 L5 panel — reach-gated access card pickup (foot height + proximity, not raycast).\n// @calls FirstPersonController, Inventory\n// @tune minFootHeight:float:0.2-1:required standing height (m)\n// @tune maxHorizontalDistance:float:0.5-2:required proximity to L5 (m)\n\nusing System.Collections;\nusing UnityEngine;\n\n/// The L5 light cover: an access card sits on top of it, out of reach from the floor. Usable only\n/// once the player's feet are high enough (standing on the stool) AND close enough horizontally —\n/// deliberately checked by actual player height/position rather than just raycast distance, since\n/// a raycast from the floor can physically reach the ceiling from across the room.\npublic class CeilingCardPanel : MonoBehaviour, IInteractable\n{\n    public float minFootHeight = 0.4f;\n    public float maxHorizontalDistance = 1f;\n    public Transform cover; // flips open when taken\n    public InventoryItem cardItem;\n\n    bool _taken;\n\n    public string InteractionPrompt => _taken ? null : \"Open light cover\";\n    public bool CanInteract => !_taken && IsPlayerCloseEnough();\n    public string BlockedReason => _taken ? null : (IsPlayerCloseEnough() ? null : \"Out of reach\");\n\n    bool IsPlayerCloseEnough()\n    {\n        var fpc = FirstPersonController.Instance;\n        if (fpc == null) return false;\n        float footY = fpc.transform.position.y;\n        Vector2 a = new Vector2(transform.position.x, transform.position.z);\n        Vector2 b = new Vector2(fpc.transform.position.x, fpc.transform.position.z);\n        return footY >= minFootHeight && Vector2.Distance(a, b) < maxHorizontalDistance;\n    }\n\n    public void Interact(GameObject interactor)\n    {\n        if (_taken) return;\n        _taken = true;\n        StartCoroutine(FlipOpen());\n        if (Inventory.Instance != null) Inventory.Instance.TryAdd(cardItem);\n    }\n\n    IEnumerator FlipOpen()\n    {\n        if (cover == null) yield break;\n        Quaternion start = cover.localRotation;\n        Quaternion end = start * Quaternion.Euler(-100f, 0, 0);\n        float t = 0f, duration = 0.4f;\n        while (t < duration)\n        {\n            t += Time.deltaTime;\n            cover.localRotation = Quaternion.Slerp(start, end, t / duration);\n            yield return null;\n        }\n        cover.localRotation = end;\n    }\n}\n"},"ClueMarker":{"path":"Assets/Scripts/Gameplay/ClueMarker.cs","role":"Passive Room 1 clue label — counts as seen just by being looked at.","source":"// @role Passive Room 1 clue label — counts as seen just by being looked at.\n// @calls CodeManager\n\nusing UnityEngine;\nusing TMPro;\n\n/// A passive clue: a world-space label that counts as \"seen\" simply by being looked at within\n/// range (no E press needed). Pulls its digit from CodeManager on Start and writes it into the\n/// label text as \"<symbol>  <digit>\". Needs a Collider on the same GameObject to be raycastable\n/// (added automatically if missing).\npublic class ClueMarker : MonoBehaviour, IClueSource\n{\n    public ClueSymbol symbol;\n    public TMP_Text label;\n\n    public ClueSymbol Symbol => symbol;\n    public int Digit { get; private set; }\n    public virtual bool IsReadable => true;\n\n    protected virtual void Awake()\n    {\n        if (GetComponent<Collider>() == null)\n        {\n            BoxCollider col = gameObject.AddComponent<BoxCollider>();\n            col.isTrigger = true;\n            col.size = new Vector3(1.6f, 0.6f, 0.2f);\n        }\n    }\n\n    protected virtual void Start()\n    {\n        Digit = CodeManager.Instance.GetDigit(symbol);\n        if (label != null)\n            label.text = $\"{CodeManager.SymbolGlyph(symbol)}  {Digit}\";\n    }\n}\n"},"ClueTracker":{"path":"Assets/Scripts/Gameplay/ClueTracker.cs","role":"Bottom-left HUD — fills in each Room 1 clue digit as the player discovers it.","source":"// @role Bottom-left HUD — fills in each Room 1 clue digit as the player discovers it.\n// @calls GameState\n\nusing TMPro;\nusing UnityEngine;\n\n/// Bottom-left HUD: 4 slots in fixed Circle/Triangle/Square/Bar order. Each starts showing the\n/// hollow symbol and flips to \"<symbol> <digit>\" the first time that clue is seen. Stays on\n/// screen for the rest of the game (Room 4 needs to read it), and mirrors every reveal into\n/// GameState.Room1ClueRecord so a scene reload (Retry Room on a later room, after Room 1 is\n/// already behind the player) can restore it instead of going blank.\npublic class ClueTracker : MonoBehaviour\n{\n    public static ClueTracker Instance { get; private set; }\n\n    public TMP_Text[] slots = new TMP_Text[4]; // indexed by ClueSymbol\n    [Tooltip(\"Set at build time so FillAllRemaining() needs no argument — a plain delegate field here wouldn't survive scene save/reload.\")]\n    public CodeManager room1Code;\n\n    readonly bool[] _seen = new bool[4];\n\n    void Awake()\n    {\n        Instance = this;\n        for (int i = 0; i < slots.Length; i++)\n            if (slots[i] != null)\n                slots[i].text = CodeManager.SymbolGlyph((ClueSymbol)i);\n\n        // Restore from a previous visit this session (e.g. reloaded because a later room failed).\n        for (int i = 0; i < 4; i++)\n        {\n            int digit = GameState.Room1ClueRecord[i];\n            if (digit >= 0) MarkSeen((ClueSymbol)i, digit);\n        }\n    }\n\n    public void MarkSeen(ClueSymbol symbol, int digit)\n    {\n        int i = (int)symbol;\n        GameState.RecordClueDigit(symbol, digit);\n        if (_seen[i]) return;\n        _seen[i] = true;\n        if (slots[i] != null)\n            slots[i].text = $\"{CodeManager.SymbolGlyph(symbol)} {digit}\";\n    }\n\n    /// Called once Room 1's door opens: any clue the player never actually looked at still gets\n    /// filled in, per spec (\"房间 1 的门打开时，如果记录还有空格，自动全部填满\").\n    public void FillAllRemaining()\n    {\n        if (room1Code == null) return;\n        for (int i = 0; i < 4; i++)\n            if (!_seen[i])\n                MarkSeen((ClueSymbol)i, room1Code.GetDigit((ClueSymbol)i));\n    }\n}\n"},"CodeManager":{"path":"Assets/Scripts/Gameplay/CodeManager.cs","role":"Room 1's 4-digit code source — reads GameState, validates keypad guesses.","source":"// @role Room 1's 4-digit code source — reads GameState, validates keypad guesses.\n// @calls GameState\n\nusing UnityEngine;\n\npublic enum ClueSymbol { Circle, Triangle, Square, Bar }\n\n/// Anything that can report a clue digit and whether it's currently legible (e.g. the light\n/// switch clue is only readable while its lamp is off).\npublic interface IClueSource\n{\n    ClueSymbol Symbol { get; }\n    int Digit { get; }\n    bool IsReadable { get; }\n}\n\n/// Reads Room 1's 4-digit code (generated once per game by GameState.BeginNewGame(), so a Retry\n/// Room reload never changes it) and validates keypad guesses against it. Digit i corresponds to\n/// symbol i (Circle=0, Triangle=1, Square=2, Bar=3); clue scripts pull their own digit from here\n/// in their own Start(), so nothing needs to push data around.\npublic class CodeManager : MonoBehaviour, IKeypadValidator\n{\n    public static CodeManager Instance { get; private set; }\n\n    void Awake()\n    {\n        Instance = this;\n        GameState.EnsureStarted();\n    }\n\n    public int GetDigit(ClueSymbol symbol) => GameState.Room1Code[(int)symbol];\n\n    public bool Validate(int[] guess)\n    {\n        if (guess == null || guess.Length != 4) return false;\n        for (int i = 0; i < 4; i++)\n            if (guess[i] != GameState.Room1Code[i]) return false;\n        return true;\n    }\n\n    public static string SymbolGlyph(ClueSymbol s) => s switch\n    {\n        ClueSymbol.Circle => \"●\",   // ●\n        ClueSymbol.Triangle => \"▲\", // ▲\n        ClueSymbol.Square => \"■\",   // ■\n        ClueSymbol.Bar => \"|\",\n        _ => \"?\"\n    };\n}\n"},"DataMatrixScreen":{"path":"Assets/Scripts/Gameplay/DataMatrixScreen.cs","role":"Room 2 matrix screen — opens the alignment UI once the calibration card is in hand.","source":"// @role Room 2 matrix screen — opens the alignment UI once the calibration card is in hand.\n// @calls CardAlignmentUI, Inventory\n\nusing UnityEngine;\n\n/// The wall-mounted matrix screen. Needs the calibration card in hand to open — once the card has\n/// been successfully aligned (and consumed), the screen stays usable so the player can come back\n/// and re-read the revealed digits.\npublic class DataMatrixScreen : MonoBehaviour, IInteractable\n{\n    public CardAlignmentUI ui;\n    public string requiredItemId = \"CalibrationCard\";\n\n    public string InteractionPrompt => \"Align card\";\n    public bool CanInteract => ui != null && (ui.Aligned || (Inventory.Instance != null && Inventory.Instance.HasItem(requiredItemId)));\n    public string BlockedReason => CanInteract ? null : \"You need the calibration card\";\n\n    public void Interact(GameObject interactor) => ui.Open();\n}\n"},"DoorwayStoolBlock":{"path":"Assets/Scripts/Gameplay/DoorwayStoolBlock.cs","role":"Room 2 — blocks/warns the player from carrying the stool out through a doorway.","source":"// @role Room 2 — blocks/warns the player from carrying the stool out through a doorway.\n// @calls StoolCarrier\n\nusing UnityEngine;\n\n/// Sits in a doorway the player shouldn't be able to carry the stool through. `sense` (a trigger\n/// collider spanning the opening) flags StoolCarrier.NearBlockedDoor while the player is in it and\n/// carrying, which PlayerInteractor turns into the \"Put the stool down first\" prompt. `solidBlock`\n/// (a non-trigger collider filling the same opening, disabled by default) is switched on whenever\n/// the player is carrying, so a CharacterController physically can't walk through — the message\n/// alone wouldn't actually stop anyone.\npublic class DoorwayStoolBlock : MonoBehaviour\n{\n    public Collider solidBlock;\n\n    void Update()\n    {\n        if (solidBlock == null) return;\n        solidBlock.enabled = StoolCarrier.Instance != null && StoolCarrier.Instance.IsCarrying;\n    }\n\n    void OnTriggerStay(Collider other)\n    {\n        if (!other.CompareTag(\"Player\") || StoolCarrier.Instance == null || !StoolCarrier.Instance.IsCarrying) return;\n        StoolCarrier.Instance.NearBlockedDoor = true;\n    }\n}\n"},"DrawerClue":{"path":"Assets/Scripts/Gameplay/DrawerClue.cs","role":"Room 1 Clue 2 setup (Triangle) — opens the drawer, reveals the paper inside.","source":"// @role Room 1 Clue 2 setup (Triangle) — opens the drawer, reveals the paper inside.\n// @calls SlideMover\n// @tune slideDuration:float:0.2-1.5:drawer slide time (s)\n\nusing UnityEngine;\n\n/// Clue 2 setup (Triangle): the drawer front. On E, slides open and reveals the paper sitting\n/// inside it (the paper itself is PaperCloseupClue, a separate IInteractable).\n[RequireComponent(typeof(SlideMover))]\npublic class DrawerClue : MonoBehaviour, IInteractable\n{\n    public Vector3 openLocalPosition;\n    public float slideDuration = 0.6f;\n    public GameObject paperObject;\n\n    SlideMover _mover;\n    bool _opened;\n\n    public string InteractionPrompt => _opened ? null : \"Open drawer\";\n    public bool CanInteract => !_opened;\n    public string BlockedReason => null;\n\n    void Awake() => _mover = GetComponent<SlideMover>();\n\n    public void Interact(GameObject interactor)\n    {\n        if (_opened) return;\n        _opened = true;\n        _mover.SlideTo(openLocalPosition, slideDuration, () =>\n        {\n            if (paperObject != null) paperObject.SetActive(true);\n        });\n    }\n}\n"},"EndMenu":{"path":"Assets/Scripts/Gameplay/EndMenu.cs","role":"Win/loss screen — Retry Room (keep progress) or Play Again (fresh game).","source":"// @role Win/loss screen — Retry Room (keep progress) or Play Again (fresh game).\n// @calls GameState\n\nusing UnityEngine;\nusing UnityEngine.SceneManagement;\nusing TMPro;\n\n/// Win -> \"YOU FOUND THE WAY OUT\" + total time, with Play Again (starts a brand new game, fresh\n/// codes) and Title. Loss -> \"THE LIGHTS WENT OUT\" + which room, with Retry Room (reloads the\n/// level scene but keeps every already-generated code and already-solved room, per GameState) and\n/// Title. `retryButton`/`playAgainButton` are toggled based on which outcome this is.\npublic class EndMenu : MonoBehaviour\n{\n    public TMP_Text titleText;\n    public TMP_Text subText;\n    public GameObject retryButton;\n    public GameObject playAgainButton;\n\n    void Start()\n    {\n        Cursor.lockState = CursorLockMode.None;\n        Cursor.visible = true;\n        if (GameState.Won)\n        {\n            titleText.text = \"YOU FOUND THE WAY OUT\";\n            int total = Mathf.Max(0, Mathf.RoundToInt(GameState.ElapsedSeconds));\n            subText.text = $\"Time: {total / 60:00}:{total % 60:00}\";\n            if (retryButton != null) retryButton.SetActive(false);\n            if (playAgainButton != null) playAgainButton.SetActive(true);\n        }\n        else\n        {\n            titleText.text = \"THE LIGHTS WENT OUT\";\n            subText.text = $\"Room {GameState.FailedRoomNumber} ran out of light.\";\n            if (retryButton != null) retryButton.SetActive(true);\n            if (playAgainButton != null) playAgainButton.SetActive(false);\n        }\n    }\n\n    /// Loss path: reload the level, keep all codes/progress (GameState untouched).\n    public void OnRetryRoomPressed()\n    {\n        SceneManager.LoadScene(\"WhiteBox_LastLight\");\n    }\n\n    /// Win path: a genuinely new game, fresh codes.\n    public void OnPlayAgainPressed()\n    {\n        GameState.BeginNewGame();\n        SceneManager.LoadScene(\"WhiteBox_LastLight\");\n    }\n\n    public void OnTitlePressed()\n    {\n        SceneManager.LoadScene(\"Title\");\n    }\n}\n"},"FirstPersonController":{"path":"Assets/Scripts/Gameplay/FirstPersonController.cs","role":"Player movement + mouse look; exposes SetInputEnabled() so UI overlays can pause it.","source":"// @role Player movement + mouse look; exposes SetInputEnabled() so UI overlays can pause it.\n// @tune moveSpeed:float:1-8:walking speed (m/s)\n// @tune mouseSensitivity:float:0.05-0.5:look sensitivity\n\nusing UnityEngine;\nusing UnityEngine.InputSystem;\n\n/// CharacterController-based first-person movement + mouse look. Uses the new Input System\n/// directly (this project's Active Input Handling is \"Input System Package (New)\" only, no\n/// legacy Input.GetAxis available), matching the style already used by StudentTools/FlyCamera.\n[RequireComponent(typeof(CharacterController))]\npublic class FirstPersonController : MonoBehaviour\n{\n    public static FirstPersonController Instance { get; private set; }\n\n    [Header(\"Move\")]\n    public float moveSpeed = 3.5f;\n    public float gravity = -9.81f;\n\n    [Header(\"Look\")]\n    public float eyeHeight = 1.6f;\n    public float mouseSensitivity = 0.12f;\n    public float minPitch = -85f;\n    public float maxPitch = 85f;\n\n    public Camera Camera { get; private set; }\n\n    CharacterController _controller;\n    float _yaw, _pitch;\n    float _verticalVelocity;\n    bool _inputEnabled = true;\n    int _resumeFrame = -1;\n    public bool InputEnabled => _inputEnabled && Time.frameCount > _resumeFrame;\n\n    void Awake()\n    {\n        Instance = this;\n        _controller = GetComponent<CharacterController>();\n\n        Camera = GetComponentInChildren<Camera>();\n        _yaw = transform.eulerAngles.y;\n    }\n\n    void Start()\n    {\n        SetInputEnabled(true);\n    }\n\n    public void SetInputEnabled(bool enabled)\n    {\n        _inputEnabled = enabled;\n        if (enabled) _resumeFrame = Time.frameCount; // Do not reuse the key press that closed an overlay.\n        Cursor.lockState = enabled ? CursorLockMode.Locked : CursorLockMode.None;\n        Cursor.visible = !enabled;\n    }\n\n    void Update()\n    {\n        if (!InputEnabled || Keyboard.current == null) return;\n\n        // Look\n        if (Mouse.current != null)\n        {\n            Vector2 delta = Mouse.current.delta.ReadValue();\n            _yaw += delta.x * mouseSensitivity;\n            _pitch = Mathf.Clamp(_pitch - delta.y * mouseSensitivity, minPitch, maxPitch);\n            transform.rotation = Quaternion.Euler(0, _yaw, 0);\n            if (Camera != null)\n                Camera.transform.localRotation = Quaternion.Euler(_pitch, 0, 0);\n        }\n\n        // Move\n        Keyboard kb = Keyboard.current;\n        float x = Axis(kb.dKey.isPressed, kb.aKey.isPressed);\n        float z = Axis(kb.wKey.isPressed, kb.sKey.isPressed);\n        Vector3 wish = transform.right * x + transform.forward * z;\n        if (wish.sqrMagnitude > 1f) wish.Normalize();\n\n        if (_controller.isGrounded && _verticalVelocity < 0f)\n            _verticalVelocity = -1f; // small stick-to-ground value, not 0 (keeps isGrounded true)\n        _verticalVelocity += gravity * Time.deltaTime;\n\n        Vector3 motion = wish * moveSpeed + Vector3.up * _verticalVelocity;\n        _controller.Move(motion * Time.deltaTime);\n    }\n\n    static float Axis(bool positive, bool negative) => (positive ? 1f : 0f) - (negative ? 1f : 0f);\n}\n"},"GameState":{"path":"Assets/Scripts/Gameplay/GameState.cs","role":"Static cross-scene game state — per-room codes, solved rooms, checkpoints, win/loss.","source":"// @role Static cross-scene game state — per-room codes, solved rooms, checkpoints, win/loss.\n\nusing System.Collections.Generic;\nusing UnityEngine;\n\n/// Cross-scene game state: a static class survives scene loads within one play session (same\n/// trick GameResult used to rely on — Time.time is not reset by a scene load). Replaces the old\n/// Room-1-only GameResult now that the game spans four rooms plus retries.\n///\n/// All per-room secrets are generated exactly once, in BeginNewGame() (called from the Title\n/// \"Start\" button and from the End screen's \"Play Again\"). A scene reload from \"Retry Room\" never\n/// calls BeginNewGame(), so the same secrets persist — only EnsureStarted() runs, which is a\n/// no-op once a game is already in progress.\npublic static class GameState\n{\n    public static bool Started { get; private set; }\n\n    // ---- Per-room secrets, generated once per game ----\n    public static int[] Room1Code { get; private set; } = new int[4]; // indexed by ClueSymbol\n    public static int[] Room2Code { get; private set; } = new int[4]; // indexed by pinhole number 1-4 (0-based)\n    public static bool[] Room3ArrowUp { get; private set; } = new bool[4]; // target breaker position per slot\n    public static ClueSymbol[] Room4MirrorOrder { get; private set; } = { ClueSymbol.Triangle, ClueSymbol.Square, ClueSymbol.Circle, ClueSymbol.Bar };\n\n    // ---- Progress ----\n    public static readonly HashSet<int> SolvedRooms = new HashSet<int>();\n    public static int CheckpointRoom { get; private set; } = 1;\n    public static List<string> CheckpointInventory { get; private set; } = new List<string>();\n\n    /// Digit seen so far for each symbol (Circle/Triangle/Square/Bar), -1 = not yet seen. Mirrors\n    /// ClueTracker's on-screen state so a scene reload (Retry Room on a later room) can restore it.\n    public static int[] Room1ClueRecord { get; private set; } = { -1, -1, -1, -1 };\n\n    // ---- Outcome ----\n    public static bool Won;\n    public static int FailedRoomNumber;\n    public static float GlobalStartTime;\n    public static float ElapsedSeconds;\n\n    public static void BeginNewGame()\n    {\n        Started = true;\n        Won = false;\n        FailedRoomNumber = 0;\n        SolvedRooms.Clear();\n        CheckpointRoom = 1;\n        CheckpointInventory = new List<string>();\n        Room1ClueRecord = new[] { -1, -1, -1, -1 };\n        GlobalStartTime = Time.time;\n        ElapsedSeconds = 0f;\n\n        for (int i = 0; i < 4; i++) Room1Code[i] = Random.Range(0, 10);\n        for (int i = 0; i < 4; i++) Room2Code[i] = Random.Range(0, 10);\n\n        // Room 3: breaker targets, excluding \"all down\" (otherwise the puzzle starts solved).\n        bool[] arrows;\n        do\n        {\n            arrows = new bool[4];\n            for (int i = 0; i < 4; i++) arrows[i] = Random.value > 0.5f;\n        } while (System.Array.TrueForAll(arrows, up => !up));\n        Room3ArrowUp = arrows;\n\n        // Room 4: a permutation of the 4 symbols, excluding the identity order (that would let\n        // the player read Room 4's password straight off Room 1's tracker without the mirror).\n        ClueSymbol[] identity = { ClueSymbol.Circle, ClueSymbol.Triangle, ClueSymbol.Square, ClueSymbol.Bar };\n        ClueSymbol[] order;\n        do { order = Shuffle(identity); } while (SequenceEquals(order, identity));\n        Room4MirrorOrder = order;\n    }\n\n    /// Called defensively by systems that need a valid game in progress (e.g. opening the level\n    /// scene directly in the editor without going through Title). Does nothing once a game has\n    /// already started, so it never clobbers an in-progress run or a retry's saved state.\n    public static void EnsureStarted()\n    {\n        if (!Started) BeginNewGame();\n    }\n\n    public static void SetCheckpoint(int roomNumber, List<string> inventorySnapshot)\n    {\n        CheckpointRoom = roomNumber;\n        CheckpointInventory = new List<string>(inventorySnapshot);\n    }\n\n    public static void MarkRoomSolved(int roomNumber) => SolvedRooms.Add(roomNumber);\n    public static bool IsRoomSolved(int roomNumber) => SolvedRooms.Contains(roomNumber);\n\n    public static void RecordClueDigit(ClueSymbol symbol, int digit) => Room1ClueRecord[(int)symbol] = digit;\n\n    public static void Fail(int roomNumber)\n    {\n        Won = false;\n        FailedRoomNumber = roomNumber;\n        ElapsedSeconds = Time.time - GlobalStartTime;\n    }\n\n    public static void WinGame()\n    {\n        Won = true;\n        ElapsedSeconds = Time.time - GlobalStartTime;\n    }\n\n    static T[] Shuffle<T>(T[] source)\n    {\n        T[] arr = (T[])source.Clone();\n        for (int i = arr.Length - 1; i > 0; i--)\n        {\n            int j = Random.Range(0, i + 1);\n            (arr[i], arr[j]) = (arr[j], arr[i]);\n        }\n        return arr;\n    }\n\n    static bool SequenceEquals(ClueSymbol[] a, ClueSymbol[] b)\n    {\n        for (int i = 0; i < a.Length; i++) if (a[i] != b[i]) return false;\n        return true;\n    }\n}\n"},"GrazingLightReveal":{"path":"Assets/Scripts/Gameplay/GrazingLightReveal.cs","role":"Reveals a surface only under a close, shallow-angle light graze (Room 3's nameplate).","source":"// @role Reveals a surface only under a close, shallow-angle light graze (Room 3's nameplate).\n// @calls InspectionLamp\n// @tune maxDistance:float:0.5-3:required lamp distance (m)\n// @tune maxGrazeAngle:float:10-45:allowed angle from parallel-to-surface (deg)\n\nusing TMPro;\nusing UnityEngine;\n\n/// Room 3's nameplate: looks completely blank under the room's own ceiling lights no matter how\n/// bright or dim they are. Only reveals its embossed arrows when ALL of these hold at once:\n/// the inspection lamp is on, it's within `maxDistance` of this surface, and its beam is grazing\n/// the surface at a shallow angle (within `maxGrazeAngle` of parallel-to-the-surface — aimed\n/// straight on gives the worst, 90-degree-from-grazing angle and reveals nothing). Clarity fades\n/// in smoothly as the angle gets closer to a perfect graze, rather than snapping on at the\n/// threshold.\npublic class GrazingLightReveal : MonoBehaviour\n{\n    [Tooltip(\"The arrow labels this reveals (alpha-faded, not SetActive, so clarity can read as a smooth fade).\")]\n    public TMP_Text[] revealedLabels = System.Array.Empty<TMP_Text>();\n    public float maxDistance = 1.5f;\n    public float maxGrazeAngle = 30f;\n\n    void Update()\n    {\n        float clarity = ComputeClarity();\n        foreach (var label in revealedLabels)\n            if (label != null) label.alpha = clarity;\n    }\n\n    float ComputeClarity()\n    {\n        var lamp = InspectionLamp.Instance;\n        if (lamp == null || !lamp.IsOn || lamp.spotLight == null) return 0f;\n\n        Transform lampT = lamp.spotLight.transform;\n        float dist = Vector3.Distance(lampT.position, transform.position);\n        if (dist > maxDistance) return 0f;\n\n        // Angle between the beam and this surface's own normal: 90 degrees means the beam runs\n        // exactly along the surface (a perfect graze); 0 or 180 means aimed straight at/away from it.\n        float angleToNormal = Vector3.Angle(lampT.forward, transform.forward);\n        float angleFromGraze = Mathf.Abs(90f - angleToNormal);\n        if (angleFromGraze > maxGrazeAngle) return 0f;\n\n        return 1f - (angleFromGraze / maxGrazeAngle);\n    }\n}\n"},"ImmediateRoomEntry":{"path":"Assets/Scripts/Gameplay/ImmediateRoomEntry.cs","role":"Room 1's \"already inside at spawn\" substitute for RoomEntryTrigger.","source":"// @role Room 1's \"already inside at spawn\" substitute for RoomEntryTrigger.\n// @calls GameState, RoomTimer, ObjectiveToast, Inventory\n\nusing System.Collections.Generic;\nusing UnityEngine;\n\n/// For the one room the player spawns directly inside of at scene load — Room 1. Every other\n/// room's \"first entry\" side effects (checkpoint, timer start, objective toast) come from walking\n/// through a RoomEntryTrigger doorway; Room 1 has no doorway to walk through at game start, so\n/// this runs the same effects from Start() instead, once, the moment the scene actually loads in\n/// Play mode (not at scene-generation time — GameState only means anything at runtime).\npublic class ImmediateRoomEntry : MonoBehaviour\n{\n    public int roomNumber;\n    public RoomTimer timer;\n    [TextArea] public string objectiveText;\n\n    void Start()\n    {\n        GameState.EnsureStarted();\n        GameState.SetCheckpoint(roomNumber, Inventory.Instance != null ? Inventory.Instance.SnapshotIds() : new List<string>());\n        timer?.BeginCountdown();\n        if (!string.IsNullOrEmpty(objectiveText) && ObjectiveToast.Instance != null)\n            ObjectiveToast.Instance.Show(objectiveText);\n    }\n}\n"},"InspectionLamp":{"path":"Assets/Scripts/Gameplay/InspectionLamp.cs","role":"Room 3+ handheld spotlight, toggled with F — follows wherever the player looks.","source":"// @role Room 3+ handheld spotlight, toggled with F — follows wherever the player looks.\n\nusing UnityEngine;\n\n/// The handheld inspection lamp Room 3's cradle assembles. Once acquired it's permanently\n/// available (not a consumable inventory item — it's needed again in Room 4), toggled with F. A\n/// Spot Light that follows wherever the player looks, used both to see in the dark and, per Room\n/// 3's nameplate and Room 4's mirror puzzle, to graze light across specific surfaces.\npublic class InspectionLamp : MonoBehaviour\n{\n    public static InspectionLamp Instance { get; private set; }\n\n    public Light spotLight;\n    public bool Acquired { get; private set; }\n    public bool IsOn { get; private set; }\n\n    void Awake()\n    {\n        Instance = this;\n        if (spotLight != null) spotLight.enabled = false;\n    }\n\n    public void Acquire()\n    {\n        Acquired = true;\n    }\n\n    public void Toggle()\n    {\n        if (!Acquired) return;\n        IsOn = !IsOn;\n        if (spotLight != null) spotLight.enabled = IsOn;\n    }\n}\n"},"InspectionLampCradle":{"path":"Assets/Scripts/Gameplay/InspectionLampCradle.cs","role":"Room 3 — assembles the inspection lamp from two carried parts.","source":"// @role Room 3 — assembles the inspection lamp from two carried parts.\n// @calls Inventory, InspectionLamp\n\nusing System.Collections;\nusing UnityEngine;\n\n/// Room 3's equipment cradle: a dusty outline waiting for two parts (base + head). E with the\n/// matching part in hand slots it in; once both are in, it auto-assembles (flash + message) and\n/// the slotted parts can't be pulled back out individually. E on the assembled lamp hands it to\n/// the player (InspectionLamp.Acquire()) and the cradle empties out visually.\npublic class InspectionLampCradle : MonoBehaviour, IInteractable\n{\n    public const string BaseItemId = \"LampBase\";\n    public const string HeadItemId = \"LampHead\";\n\n    public GameObject outlineVisual;\n    public GameObject baseOnlyVisual;\n    public GameObject headOnlyVisual;\n    public GameObject assembledVisual;\n    public Renderer assembledFlashRenderer;\n\n    bool _hasBase, _hasHead, _assembled, _takenByPlayer;\n\n    public bool CanInteract\n    {\n        get\n        {\n            if (_takenByPlayer) return false;\n            if (_assembled) return true;\n            bool canPlaceBase = !_hasBase && Inventory.Instance != null && Inventory.Instance.HasItem(BaseItemId);\n            bool canPlaceHead = !_hasHead && Inventory.Instance != null && Inventory.Instance.HasItem(HeadItemId);\n            return canPlaceBase || canPlaceHead;\n        }\n    }\n\n    public string InteractionPrompt\n    {\n        get\n        {\n            if (_takenByPlayer) return null;\n            if (_assembled) return \"Take inspection lamp\";\n            return CanInteract ? \"Place part\" : null;\n        }\n    }\n\n    public string BlockedReason\n    {\n        get\n        {\n            if (_takenByPlayer || _assembled) return null;\n            return (!_hasBase && !_hasHead) ? \"Empty cradle\" : null;\n        }\n    }\n\n    void Start() => UpdateVisual();\n\n    public void Interact(GameObject interactor)\n    {\n        if (_takenByPlayer) return;\n\n        if (_assembled)\n        {\n            _takenByPlayer = true;\n            if (InspectionLamp.Instance != null) InspectionLamp.Instance.Acquire();\n            UpdateVisual();\n            return;\n        }\n\n        if (!_hasBase && Inventory.Instance != null && Inventory.Instance.HasItem(BaseItemId))\n        {\n            Inventory.Instance.Remove(BaseItemId);\n            _hasBase = true;\n        }\n        else if (!_hasHead && Inventory.Instance != null && Inventory.Instance.HasItem(HeadItemId))\n        {\n            Inventory.Instance.Remove(HeadItemId);\n            _hasHead = true;\n        }\n\n        if (_hasBase && _hasHead && !_assembled)\n        {\n            _assembled = true;\n            Inventory.Instance?.ShowMessage(\"Inspection lamp assembled\");\n            StartCoroutine(FlashOnce());\n        }\n\n        UpdateVisual();\n    }\n\n    void UpdateVisual()\n    {\n        if (outlineVisual != null) outlineVisual.SetActive(!_assembled);\n        if (baseOnlyVisual != null) baseOnlyVisual.SetActive(_hasBase && !_assembled);\n        if (headOnlyVisual != null) headOnlyVisual.SetActive(_hasHead && !_assembled);\n        if (assembledVisual != null) assembledVisual.SetActive(_assembled && !_takenByPlayer);\n    }\n\n    IEnumerator FlashOnce()\n    {\n        if (assembledFlashRenderer == null) yield break;\n        Color baseColor = assembledFlashRenderer.material.color;\n        assembledFlashRenderer.material.color = Color.white;\n        yield return new WaitForSeconds(0.15f);\n        assembledFlashRenderer.material.color = baseColor;\n    }\n}\n"},"Inventory":{"path":"Assets/Scripts/Gameplay/Inventory.cs","role":"Bottom-center held-item row (max 4) — puzzle objects auto-use whatever item they need.","source":"// @role Bottom-center held-item row (max 4) — puzzle objects auto-use whatever item they need.\n\nusing System.Collections;\nusing System.Collections.Generic;\nusing TMPro;\nusing UnityEngine;\nusing UnityEngine.UI;\n\n/// A held item. Whitebox-styled: no icon art, just a flat color swatch + short label, matching\n/// the rest of the level's \"colored primitives\" look.\n[System.Serializable]\npublic struct InventoryItem\n{\n    public string id;\n    public string displayName;\n    public Color iconColor;\n    public InventoryItem(string id, string displayName, Color iconColor)\n    {\n        this.id = id; this.displayName = displayName; this.iconColor = iconColor;\n    }\n}\n\n/// Bottom-center held-item row, max 4 slots. The player never manually selects a slot — whatever\n/// puzzle object accepts a given item id just checks HasItem(id) itself and calls Remove(id) as\n/// part of its own Interact(), so \"auto-use on E\" needs no special wiring here.\npublic class Inventory : MonoBehaviour\n{\n    public static Inventory Instance { get; private set; }\n    public const int MaxSlots = 4;\n\n    public Image[] slotIcons = new Image[MaxSlots];\n    public TMP_Text pickupToastText;\n    public float pickupToastDuration = 1.5f;\n\n    readonly List<InventoryItem> _items = new List<InventoryItem>();\n    Coroutine _toastRoutine;\n\n    void Awake()\n    {\n        Instance = this;\n        if (pickupToastText != null) pickupToastText.alpha = 0f;\n        RefreshUI();\n    }\n\n    public bool HasItem(string id) => _items.Exists(i => i.id == id);\n\n    public bool TryAdd(InventoryItem item)\n    {\n        if (_items.Count >= MaxSlots || HasItem(item.id)) return false;\n        _items.Add(item);\n        RefreshUI();\n        ShowMessage($\"Picked up: {item.displayName}\");\n        return true;\n    }\n\n    public void Remove(string id)\n    {\n        _items.RemoveAll(i => i.id == id);\n        RefreshUI();\n    }\n\n    public void Clear()\n    {\n        _items.Clear();\n        RefreshUI();\n    }\n\n    public List<string> SnapshotIds() => _items.ConvertAll(i => i.id);\n\n    void RefreshUI()\n    {\n        for (int i = 0; i < slotIcons.Length; i++)\n        {\n            if (slotIcons[i] == null) continue;\n            bool filled = i < _items.Count;\n            slotIcons[i].gameObject.SetActive(filled);\n            if (filled) slotIcons[i].color = _items[i].iconColor;\n        }\n    }\n\n    /// Reused for any brief \"the player should notice this\" line, not just pickups — e.g. a\n    /// card reader's \"Access denied\".\n    public void ShowMessage(string text)\n    {\n        if (pickupToastText == null) return;\n        if (_toastRoutine != null) StopCoroutine(_toastRoutine);\n        _toastRoutine = StartCoroutine(ToastCo(text));\n    }\n\n    IEnumerator ToastCo(string text)\n    {\n        pickupToastText.text = text;\n        pickupToastText.alpha = 1f;\n        yield return new WaitForSeconds(pickupToastDuration);\n        float t = 0f;\n        const float fade = 0.4f;\n        while (t < fade)\n        {\n            t += Time.deltaTime;\n            pickupToastText.alpha = Mathf.Lerp(1f, 0f, t / fade);\n            yield return null;\n        }\n        pickupToastText.alpha = 0f;\n    }\n}\n"},"InventoryPickup":{"path":"Assets/Scripts/Gameplay/InventoryPickup.cs","role":"Generic world pickup — E adds it to the inventory and hides it.","source":"// @role Generic world pickup — E adds it to the inventory and hides it.\n// @calls Inventory\n\nusing UnityEngine;\n\n/// Generic \"E to pick up, goes into inventory, disappears from the world\" object. Reused across\n/// rooms for anything that's just a carried item rather than a bespoke mechanic (Room 2's\n/// calibration card, Room 3's lamp parts, ...).\npublic class InventoryPickup : MonoBehaviour, IInteractable\n{\n    public InventoryItem item;\n    public string prompt = \"Pick up\";\n\n    public string InteractionPrompt => prompt;\n    public bool CanInteract => true;\n    public string BlockedReason => null;\n\n    public void Interact(GameObject interactor)\n    {\n        if (Inventory.Instance != null && Inventory.Instance.TryAdd(item))\n            gameObject.SetActive(false);\n    }\n}\n"},"KeypadController":{"path":"Assets/Scripts/Gameplay/KeypadController.cs","role":"World-space keypad prop — E opens its KeypadUI panel.","source":"// @role World-space keypad prop — E opens its KeypadUI panel.\n// @calls KeypadUI\n\nusing UnityEngine;\n\n/// The world-space keypad panel. E opens its input UI. `ui` is assigned at build time to the\n/// specific KeypadUI panel this keypad owns — each door gets its own KeypadUI instance now (Room\n/// 1 and Room 2 both have one), so this no longer reaches for a global singleton.\npublic class KeypadController : MonoBehaviour, IInteractable\n{\n    public KeypadUI ui;\n\n    public string InteractionPrompt => ui != null && ui.Solved ? null : \"Use keypad\";\n    public bool CanInteract => ui != null && !ui.Solved;\n    public string BlockedReason => null;\n\n    public void Interact(GameObject interactor) => ui.Open();\n}\n"},"KeypadDigitButton":{"path":"Assets/Scripts/Gameplay/KeypadDigitButton.cs","role":"UI button wrapper — forwards a digit press to its KeypadUI.","source":"// @role UI button wrapper — forwards a digit press to its KeypadUI.\n// @calls KeypadUI\n\nusing UnityEngine;\n\n/// Tiny per-button helper so each of the 0-9 buttons can bind a parameterless UnityEvent\n/// (Button.onClick takes no arguments) back to KeypadUI.PressDigit(int). Bound to a specific\n/// `owner` panel at build time rather than a static singleton, since multiple keypads (Room 1,\n/// Room 2, ...) now coexist in the same scene.\npublic class KeypadDigitButton : MonoBehaviour\n{\n    public KeypadUI owner;\n    public int digit;\n    public void Press() => owner.PressDigit(digit);\n}\n"},"KeypadUI":{"path":"Assets/Scripts/Gameplay/KeypadUI.cs","role":"Shared exit keypad (Room 1 + Room 2) — checks a guess, slides the door open.","source":"// @role Shared exit keypad (Room 1 + Room 2) — checks a guess, slides the door open.\n// @calls IKeypadValidator, ClueTracker, RoomTimer, SlideMover, GameState\n// @tune doorSlideDuration:float:0.5-2:door open animation time\n// @tune wrongGuessPenalty:float:0-30:seconds lost per wrong code\n\nusing System.Collections;\nusing System.Collections.Generic;\nusing UnityEngine;\nusing UnityEngine.InputSystem;\nusing TMPro;\n\n/// The 4-digit input panel: shows the fixed Circle/Triangle/Square/Bar symbols above 4 slots\n/// (toggle off `showSymbols` for a keypad that shouldn't give the symbol hint away, e.g. Room\n/// 2's), takes digits from the 0-9 buttons, Clear resets, Confirm checks the guess against\n/// `validatorBehaviour` (cast to IKeypadValidator). Wrong code -> the panel shakes and clears (no\n/// per-digit feedback), then docks `wrongGuessPenalty` seconds off `penaltyTimer` if both are set.\n/// Right code -> panel closes, the exit door slides open, and `clueTrackerToFill` (if set) fills\n/// in any still-blank clue slots.\n///\n/// Every cross-object hookup here is a plain serializable Component reference rather than a\n/// System.Action/interface-typed field deliberately: this scene is authored once at editor time\n/// and then saved/reloaded at Play time (including every Retry Room), and Unity's serializer\n/// silently drops plain delegates and bare interface fields on that round trip — they'd read back\n/// as null the moment the player actually plays the game, not just in the editor session that\n/// built them.\n///\n/// Each door gets its own KeypadUI instance (no longer a hard scene-wide singleton), so several\n/// can coexist. `Instance` is kept only as a convenience pointer to whichever one was built most\n/// recently, for tests/tools that only ever expect one panel at a time.\npublic class KeypadUI : MonoBehaviour\n{\n    public static KeypadUI Instance { get; private set; }\n\n    public GameObject panelRoot;\n    public TMP_Text[] digitSlots = new TMP_Text[4];   // entered value display, left to right\n    public TMP_Text[] symbolLabels = new TMP_Text[4]; // fixed Circle/Triangle/Square/Bar glyphs\n    public bool showSymbols = true;\n    public SlideMover door;\n    public Vector3 doorOpenLocalPosition;\n    public float doorSlideDuration = 1f;\n\n    /// Must implement IKeypadValidator (CodeManager for Room 1; a room-specific validator for\n    /// later rooms). A MonoBehaviour reference rather than the interface type so it survives\n    /// Unity's scene serialization — see class remarks.\n    public MonoBehaviour validatorBehaviour;\n    IKeypadValidator Validator => validatorBehaviour as IKeypadValidator;\n\n    public ClueTracker clueTrackerToFill; // filled on solve, if set\n    public RoomTimer penaltyTimer;        // penalized on a wrong guess, if set\n    public float wrongGuessPenalty = 0f;\n\n    [Tooltip(\"1-4, or 0 to skip. If GameState already has this room marked solved when the scene loads (e.g. Retry Room after a LATER room failed), the door snaps open immediately instead of making the player re-solve an already-passed room.\")]\n    public int roomNumberForFastForward;\n\n    public bool Solved { get; private set; }\n    public bool IsOpen => panelRoot != null && panelRoot.activeSelf;\n\n    readonly List<int> _entered = new List<int>();\n    static readonly Key[] DigitKeys = { Key.Digit0, Key.Digit1, Key.Digit2, Key.Digit3, Key.Digit4, Key.Digit5, Key.Digit6, Key.Digit7, Key.Digit8, Key.Digit9 };\n    static readonly Key[] NumpadKeys = { Key.Numpad0, Key.Numpad1, Key.Numpad2, Key.Numpad3, Key.Numpad4, Key.Numpad5, Key.Numpad6, Key.Numpad7, Key.Numpad8, Key.Numpad9 };\n    bool _rejecting;\n    RectTransform _panelRect;\n    Vector2 _panelBasePos;\n\n    void Awake()\n    {\n        Instance = this;\n        _panelRect = panelRoot.GetComponent<RectTransform>();\n        if (_panelRect != null) _panelBasePos = _panelRect.anchoredPosition;\n\n        for (int i = 0; i < 4; i++)\n        {\n            if (symbolLabels[i] == null) continue;\n            symbolLabels[i].text = CodeManager.SymbolGlyph((ClueSymbol)i);\n            symbolLabels[i].gameObject.SetActive(showSymbols);\n        }\n\n        panelRoot.SetActive(false);\n    }\n\n    void Start()\n    {\n        if (roomNumberForFastForward > 0 && GameState.IsRoomSolved(roomNumberForFastForward))\n        {\n            Solved = true;\n            if (door != null) door.transform.localPosition = doorOpenLocalPosition;\n        }\n    }\n\n    public void Open()\n    {\n        if (Solved || IsOpen) return;\n        if (PaperCloseupUI.Instance != null && PaperCloseupUI.Instance.IsOpen) PaperCloseupUI.Instance.Close();\n        panelRoot.SetActive(true);\n        _entered.Clear();\n        RefreshDisplay();\n        FirstPersonController.Instance.SetInputEnabled(false);\n    }\n\n    public void Close()\n    {\n        StopAllCoroutines();\n        _rejecting = false;\n        if (_panelRect != null) _panelRect.anchoredPosition = _panelBasePos;\n        panelRoot.SetActive(false);\n        FirstPersonController.Instance.SetInputEnabled(true);\n    }\n\n    public void PressDigit(int digit)\n    {\n        if (!IsOpen || _rejecting || digit < 0 || digit > 9 || _entered.Count >= 4) return;\n        _entered.Add(digit);\n        RefreshDisplay();\n    }\n\n    public void PressClear()\n    {\n        if (!IsOpen || _rejecting) return;\n        _entered.Clear();\n        RefreshDisplay();\n    }\n\n    public void PressConfirm()\n    {\n        if (!IsOpen || _rejecting || _entered.Count != 4 || Validator == null) return;\n\n        if (Validator.Validate(_entered.ToArray()))\n        {\n            Solved = true;\n            panelRoot.SetActive(false);\n            FirstPersonController.Instance.SetInputEnabled(true);\n            door.SlideTo(doorOpenLocalPosition, doorSlideDuration);\n            if (clueTrackerToFill != null) clueTrackerToFill.FillAllRemaining();\n        }\n        else\n        {\n            StartCoroutine(ShakeThenClear());\n            if (penaltyTimer != null && wrongGuessPenalty > 0f) penaltyTimer.Penalty(wrongGuessPenalty);\n        }\n    }\n\n    void RefreshDisplay()\n    {\n        for (int i = 0; i < 4; i++)\n            if (digitSlots[i] != null)\n                digitSlots[i].text = i < _entered.Count ? _entered[i].ToString() : \"_\";\n    }\n\n    IEnumerator ShakeThenClear()\n    {\n        _rejecting = true;\n        if (_panelRect != null)\n        {\n            float duration = 0.35f, t = 0f, magnitude = 18f, frequency = 28f;\n            while (t < duration)\n            {\n                t += Time.deltaTime;\n                float damp = 1f - (t / duration);\n                float x = Mathf.Sin(t * frequency) * magnitude * damp;\n                _panelRect.anchoredPosition = _panelBasePos + new Vector2(x, 0f);\n                yield return null;\n            }\n            _panelRect.anchoredPosition = _panelBasePos;\n        }\n        _entered.Clear();\n        RefreshDisplay();\n        _rejecting = false;\n    }\n\n    void Update()\n    {\n        if (!IsOpen || Keyboard.current == null) return;\n        var kb = Keyboard.current;\n        if (kb.escapeKey.wasPressedThisFrame) { Close(); return; }\n        for (int digit = 0; digit <= 9; digit++)\n            if (kb[DigitKeys[digit]].wasPressedThisFrame ||\n                kb[NumpadKeys[digit]].wasPressedThisFrame) PressDigit(digit);\n        if (kb.backspaceKey.wasPressedThisFrame || kb.deleteKey.wasPressedThisFrame) PressClear();\n        if (kb.enterKey.wasPressedThisFrame || kb.numpadEnterKey.wasPressedThisFrame) PressConfirm();\n    }\n}\n"},"LightSwitchClue":{"path":"Assets/Scripts/Gameplay/LightSwitchClue.cs","role":"Room 1 Clue 4 (Bar) — toggles a light; the clue text is only readable while it's off.","source":"// @role Room 1 Clue 4 (Bar) — toggles a light; the clue text is only readable while it's off.\n// @calls CodeManager\n// @tune fadeDuration:float:0.2-1:light/text fade time (s)\n\nusing System.Collections;\nusing UnityEngine;\nusing TMPro;\n\n/// Clue 4 (Bar): the switch. E toggles the nearest ceiling light; the clue text next to it\n/// fades between near-invisible (light on) and fully visible (light off) over ~0.5s. If\n/// RoomTimer later kills this same light on its own, ForceReveal() locks the text visible\n/// regardless of switch state, per spec.\npublic class LightSwitchClue : MonoBehaviour, IInteractable, IClueSource\n{\n    public ClueSymbol symbol = ClueSymbol.Bar;\n    public Light targetLight;\n    public Renderer targetPanelRenderer; // the ceiling light's emissive panel mesh\n    public TMP_Text label;\n    public float fadeDuration = 0.5f;\n\n    public ClueSymbol Symbol => symbol;\n    public int Digit { get; private set; }\n    public bool IsReadable => _forceRevealed || !_lightOn;\n\n    public string InteractionPrompt => _forceRevealed ? null : (_lightOn ? \"Turn off light\" : \"Turn on light\");\n    public bool CanInteract => !_forceRevealed;\n    public string BlockedReason => null;\n\n    bool _lightOn = true;\n    bool _forceRevealed;\n    float _baseIntensity;\n    Color _baseEmission;\n    Material _panelInstance;\n\n    void Start()\n    {\n        Digit = CodeManager.Instance.GetDigit(symbol);\n        if (label != null) label.text = $\"{CodeManager.SymbolGlyph(symbol)}  {Digit}\";\n\n        _baseIntensity = targetLight != null ? targetLight.intensity : 1f;\n        if (targetPanelRenderer != null)\n        {\n            _panelInstance = targetPanelRenderer.material; // auto-instances a per-renderer copy\n            _baseEmission = _panelInstance.GetColor(\"_EmissionColor\");\n        }\n        ApplyImmediate();\n    }\n\n    public void Interact(GameObject interactor)\n    {\n        if (_forceRevealed) return;\n        _lightOn = !_lightOn;\n        StopAllCoroutines();\n        StartCoroutine(Fade());\n    }\n\n    /// Called by RoomTimer when its countdown extinguishes this exact light.\n    public void ForceReveal()\n    {\n        _forceRevealed = true;\n        _lightOn = false;\n        StopAllCoroutines();\n        if (label != null) label.alpha = 1f;\n    }\n\n    void ApplyImmediate()\n    {\n        if (label != null) label.alpha = _lightOn ? 0.05f : 1f;\n    }\n\n    IEnumerator Fade()\n    {\n        float startAlpha = label != null ? label.alpha : 0f;\n        float endAlpha = _lightOn ? 0.05f : 1f;\n        float startIntensity = targetLight != null ? targetLight.intensity : 0f;\n        float endIntensity = _lightOn ? _baseIntensity : 0f;\n        Color startEmission = _panelInstance != null ? _panelInstance.GetColor(\"_EmissionColor\") : Color.black;\n        Color endEmission = _lightOn ? _baseEmission : Color.black;\n\n        float t = 0f;\n        while (t < fadeDuration)\n        {\n            t += Time.deltaTime;\n            float k = Mathf.Clamp01(t / fadeDuration);\n            if (label != null) label.alpha = Mathf.Lerp(startAlpha, endAlpha, k);\n            if (targetLight != null) targetLight.intensity = Mathf.Lerp(startIntensity, endIntensity, k);\n            if (_panelInstance != null) _panelInstance.SetColor(\"_EmissionColor\", Color.Lerp(startEmission, endEmission, k));\n            yield return null;\n        }\n        if (label != null) label.alpha = endAlpha;\n        if (targetLight != null) targetLight.intensity = endIntensity;\n        if (_panelInstance != null) _panelInstance.SetColor(\"_EmissionColor\", endEmission);\n    }\n}\n"},"MainBreaker":{"path":"Assets/Scripts/Gameplay/MainBreaker.cs","role":"Room 3 — checks all 4 breakers against the nameplate pattern, opens the door or penalizes.","source":"// @role Room 3 — checks all 4 breakers against the nameplate pattern, opens the door or penalizes.\n// @calls GameState, RoomTimer, SlideMover\n// @tune wrongPenalty:float:0-30:seconds lost per wrong submit\n\nusing UnityEngine;\n\n/// The larger main breaker: E checks the 4 small breakers against GameState.Room3ArrowUp. All\n/// correct -> status light green, door opens. Any wrong -> all 4 breakers snap back down (no hint\n/// which ones were wrong) and a time penalty applies.\npublic class MainBreaker : MonoBehaviour, IInteractable\n{\n    public BreakerSwitch[] breakers = new BreakerSwitch[4];\n    public SlideMover door;\n    public Vector3 doorOpenLocalPosition;\n    public Renderer statusLightRenderer;\n    public Color deniedColor = new Color(0.9f, 0.15f, 0.1f);\n    public Color grantedColor = new Color(0.2f, 0.85f, 0.3f);\n    public RoomTimer penaltyTimer;\n    public float wrongPenalty = 15f;\n\n    [Tooltip(\"If GameState already has Room 3 marked solved when the scene loads (Retry Room after a later room failed), snap the door open immediately.\")]\n    public int roomNumberForFastForward = 3;\n\n    bool _solved;\n\n    public string InteractionPrompt => _solved ? null : \"Throw main breaker\";\n    public bool CanInteract => !_solved;\n    public string BlockedReason => null;\n\n    void Start()\n    {\n        if (statusLightRenderer != null) statusLightRenderer.material.color = deniedColor;\n        if (roomNumberForFastForward > 0 && GameState.IsRoomSolved(roomNumberForFastForward))\n        {\n            _solved = true;\n            if (statusLightRenderer != null) statusLightRenderer.material.color = grantedColor;\n            if (door != null) door.transform.localPosition = doorOpenLocalPosition;\n        }\n    }\n\n    public void Interact(GameObject interactor)\n    {\n        if (_solved) return;\n\n        bool allCorrect = true;\n        for (int i = 0; i < breakers.Length && i < GameState.Room3ArrowUp.Length; i++)\n        {\n            if (breakers[i] == null || breakers[i].IsUp != GameState.Room3ArrowUp[i]) { allCorrect = false; break; }\n        }\n\n        if (allCorrect)\n        {\n            _solved = true;\n            if (statusLightRenderer != null) statusLightRenderer.material.color = grantedColor;\n            if (door != null) door.SlideTo(doorOpenLocalPosition, 1f);\n        }\n        else\n        {\n            foreach (var b in breakers) b?.SetUp(false);\n            if (penaltyTimer != null) penaltyTimer.Penalty(wrongPenalty);\n        }\n    }\n}\n"},"MovableCabinetClue":{"path":"Assets/Scripts/Gameplay/MovableCabinetClue.cs","role":"Room 1 Clue 1 (Circle) — slides the displaced cabinet back, reveals hidden wall text.","source":"// @role Room 1 Clue 1 (Circle) — slides the displaced cabinet back, reveals hidden wall text.\n// @calls SlideMover\n// @tune slideDuration:float:0.3-2:cabinet slide time (s)\n\nusing UnityEngine;\n\n/// Clue 1 (Circle): the displaced cabinet. On E, slides back to its original spot (the clean\n/// patch), exposing the wall text that was hidden behind it while it sat in the corner.\n[RequireComponent(typeof(SlideMover))]\npublic class MovableCabinetClue : MonoBehaviour, IInteractable\n{\n    public Vector3 restingLocalPosition;\n    public float slideDuration = 1f;\n    [Tooltip(\"Wall text this reveals (SetActive(true)) once the cabinet finishes sliding away.\")]\n    public GameObject revealTarget;\n\n    SlideMover _mover;\n    bool _moved;\n\n    public string InteractionPrompt => _moved ? null : \"Move cabinet\";\n    public bool CanInteract => !_moved;\n    public string BlockedReason => null;\n\n    void Awake() => _mover = GetComponent<SlideMover>();\n\n    public void Interact(GameObject interactor)\n    {\n        if (_moved) return;\n        _moved = true;\n        _mover.SlideTo(restingLocalPosition, slideDuration, () =>\n        {\n            if (revealTarget != null) revealTarget.SetActive(true);\n        });\n    }\n}\n"},"NameplateArrows":{"path":"Assets/Scripts/Gameplay/NameplateArrows.cs","role":"Fills Room 3's nameplate arrows from the random breaker target pattern.","source":"// @role Fills Room 3's nameplate arrows from the random breaker target pattern.\n// @calls GameState\n\nusing TMPro;\nusing UnityEngine;\n\n/// Fills Room 3's nameplate arrows from GameState.Room3ArrowUp at Awake() — the real values only\n/// exist once a game is actually in progress, so the editor generator lays out empty labels and\n/// this fills them in at runtime (same reasoning as CardAlignmentUI's matrix digits in Room 2).\npublic class NameplateArrows : MonoBehaviour\n{\n    public TMP_Text[] arrows = System.Array.Empty<TMP_Text>();\n\n    void Awake()\n    {\n        GameState.EnsureStarted();\n        for (int i = 0; i < arrows.Length && i < GameState.Room3ArrowUp.Length; i++)\n            if (arrows[i] != null)\n                arrows[i].text = GameState.Room3ArrowUp[i] ? \"▲\" : \"▼\"; // up / down triangle\n    }\n}\n"},"ObjectiveToast":{"path":"Assets/Scripts/Gameplay/ObjectiveToast.cs","role":"Top-center fade-in room objective line; Tab replays it.","source":"// @role Top-center fade-in room objective line; Tab replays it.\n// @tune holdDuration:float:2-10:how long the toast stays fully visible (s)\n\nusing System.Collections;\nusing TMPro;\nusing UnityEngine;\n\n/// Top-center \"what am I trying to do here\" line. Fades in, holds for `holdDuration`, fades out.\n/// Tab re-plays whatever the current room's text is (handled by PlayerInteractor, which calls\n/// ReplayCurrent()) even after it has already faded out once.\npublic class ObjectiveToast : MonoBehaviour\n{\n    public static ObjectiveToast Instance { get; private set; }\n\n    public TMP_Text label;\n    public float holdDuration = 5f;\n    public float fadeDuration = 0.6f;\n\n    string _currentText = \"\";\n    Coroutine _running;\n\n    void Awake()\n    {\n        Instance = this;\n        if (label != null) label.alpha = 0f;\n    }\n\n    /// Shows new text for the room the player just entered, and remembers it as \"current\" so Tab\n    /// can bring it back later.\n    public void Show(string text)\n    {\n        _currentText = text;\n        Replay();\n    }\n\n    /// Re-shows whatever text is current (Tab), even if nothing changed.\n    public void ReplayCurrent() => Replay();\n\n    void Replay()\n    {\n        if (string.IsNullOrEmpty(_currentText) || label == null) return;\n        if (_running != null) StopCoroutine(_running);\n        _running = StartCoroutine(FadeInHoldFadeOut());\n    }\n\n    IEnumerator FadeInHoldFadeOut()\n    {\n        label.text = _currentText;\n        yield return Fade(label.alpha, 1f);\n        yield return new WaitForSeconds(holdDuration);\n        yield return Fade(1f, 0f);\n    }\n\n    IEnumerator Fade(float from, float to)\n    {\n        float t = 0f;\n        while (t < fadeDuration)\n        {\n            t += Time.deltaTime;\n            label.alpha = Mathf.Lerp(from, to, t / fadeDuration);\n            yield return null;\n        }\n        label.alpha = to;\n    }\n}\n"},"PaperCloseupClue":{"path":"Assets/Scripts/Gameplay/PaperCloseupClue.cs","role":"Room 1 Clue 2 (Triangle) — opens the paper close-up, marks the clue seen.","source":"// @role Room 1 Clue 2 (Triangle) — opens the paper close-up, marks the clue seen.\n// @calls PaperCloseupUI, CodeManager, ClueTracker\n\nusing UnityEngine;\n\n/// Clue 2 (Triangle): the paper itself. E opens the full-screen close-up UI; the clue only\n/// counts as \"seen\" once that close-up has been opened (looking at the tiny paper in the world\n/// isn't legible enough on its own, per spec).\npublic class PaperCloseupClue : MonoBehaviour, IInteractable\n{\n    public ClueSymbol symbol = ClueSymbol.Triangle;\n\n    int _digit;\n    bool _digitReady;\n    bool _everOpened;\n\n    public string InteractionPrompt => \"Read note\";\n    public bool CanInteract => true;\n    public string BlockedReason => null;\n\n    void EnsureDigit()\n    {\n        if (_digitReady) return;\n        _digit = CodeManager.Instance.GetDigit(symbol);\n        _digitReady = true;\n    }\n\n    public void Interact(GameObject interactor)\n    {\n        EnsureDigit();\n        PaperCloseupUI.Instance.Open(symbol, _digit);\n        if (!_everOpened)\n        {\n            _everOpened = true;\n            ClueTracker.Instance.MarkSeen(symbol, _digit);\n        }\n    }\n}\n"},"PaperCloseupUI":{"path":"Assets/Scripts/Gameplay/PaperCloseupUI.cs","role":"Full-screen paper-reading overlay for Room 1's Triangle clue.","source":"// @role Full-screen paper-reading overlay for Room 1's Triangle clue.\n// @calls FirstPersonController\n\nusing UnityEngine;\nusing UnityEngine.InputSystem;\nusing TMPro;\n\n/// Full-screen \"reading the paper\" overlay. E or Esc closes it again.\npublic class PaperCloseupUI : MonoBehaviour\n{\n    public static PaperCloseupUI Instance { get; private set; }\n\n    public GameObject panelRoot;\n    public TMP_Text symbolDigitText;\n\n    void Awake()\n    {\n        Instance = this;\n        if (panelRoot != null) panelRoot.SetActive(false);\n    }\n\n    int _openedFrame;\n\n    public bool IsOpen => panelRoot != null && panelRoot.activeSelf;\n\n    public void Open(ClueSymbol symbol, int digit)\n    {\n        if (KeypadUI.Instance != null && KeypadUI.Instance.IsOpen) return;\n        _openedFrame = Time.frameCount;\n        panelRoot.SetActive(true);\n        symbolDigitText.text = $\"{CodeManager.SymbolGlyph(symbol)}   {digit}\";\n        FirstPersonController.Instance.SetInputEnabled(false);\n    }\n\n    public void Close()\n    {\n        panelRoot.SetActive(false);\n        FirstPersonController.Instance.SetInputEnabled(true);\n    }\n\n    void Update()\n    {\n        if (!IsOpen || Time.frameCount == _openedFrame || Keyboard.current == null) return;\n        if (Keyboard.current.eKey.wasPressedThisFrame || Keyboard.current.escapeKey.wasPressedThisFrame)\n            Close();\n    }\n}\n"},"PlayerInteractor":{"path":"Assets/Scripts/Gameplay/PlayerInteractor.cs","role":"Raycasts for interactables each frame and routes E / Tab / F input to them.","source":"// @role Raycasts for interactables each frame and routes E / Tab / F input to them.\n// @calls ClueTracker, StoolCarrier, ObjectiveToast, InspectionLamp\n// @tune range:float:1-4:interaction raycast distance (m)\n\nusing UnityEngine;\nusing UnityEngine.InputSystem;\nusing TMPro;\n\n/// Raycasts forward from the player camera every frame, out to `range`. If it hits an\n/// IInteractable, shows its prompt under the crosshair and calls Interact() on E. Independently,\n/// if it hits an IClueSource that is currently readable, reports it to ClueTracker — clue\n/// \"sightings\" don't require pressing E, just looking.\npublic class PlayerInteractor : MonoBehaviour\n{\n    public Camera playerCamera;\n    public TMP_Text promptText;\n    public float range = 2f;\n\n    IInteractable _current;\n\n    void Update()\n    {\n        if (playerCamera == null) return;\n        if (FirstPersonController.Instance != null && !FirstPersonController.Instance.InputEnabled)\n        {\n            if (promptText != null) promptText.text = \"\";\n            return;\n        }\n\n        Ray ray = new Ray(playerCamera.transform.position, playerCamera.transform.forward);\n        bool hitSomething = Physics.Raycast(ray, out RaycastHit hit, range, ~0, QueryTriggerInteraction.Collide);\n\n        bool carryingStool = StoolCarrier.Instance != null && StoolCarrier.Instance.IsCarrying;\n        _current = hitSomething ? hit.collider.GetComponentInParent<IInteractable>() : null;\n\n        if (promptText != null)\n        {\n            // Carrying the stool overrides whatever's under the crosshair: E always tries to\n            // place it, and being near a doorway while carrying always warns about it, regardless\n            // of what the player happens to be looking at.\n            if (carryingStool && StoolCarrier.Instance.NearBlockedDoor)\n                promptText.text = \"Put the stool down first\";\n            else if (carryingStool)\n                promptText.text = \"E   Place stool\";\n            else if (_current != null && _current.CanInteract && !string.IsNullOrEmpty(_current.InteractionPrompt))\n                promptText.text = $\"E   {_current.InteractionPrompt}\";\n            else if (_current != null && !_current.CanInteract && !string.IsNullOrEmpty(_current.BlockedReason))\n                promptText.text = _current.BlockedReason;\n            else\n                promptText.text = \"\";\n        }\n\n        if (hitSomething)\n        {\n            IClueSource clue = hit.collider.GetComponentInParent<IClueSource>();\n            if (clue != null && clue.IsReadable && ClueTracker.Instance != null)\n                ClueTracker.Instance.MarkSeen(clue.Symbol, clue.Digit);\n        }\n\n        if (Keyboard.current != null)\n        {\n            if (Keyboard.current.eKey.wasPressedThisFrame)\n            {\n                if (carryingStool) StoolCarrier.Instance.TryPlace();\n                else if (_current != null && _current.CanInteract) _current.Interact(gameObject);\n            }\n\n            if (Keyboard.current.tabKey.wasPressedThisFrame && ObjectiveToast.Instance != null)\n                ObjectiveToast.Instance.ReplayCurrent();\n\n            if (Keyboard.current.fKey.wasPressedThisFrame && InspectionLamp.Instance != null)\n                InspectionLamp.Instance.Toggle();\n        }\n    }\n}\n"},"Room2CodeValidator":{"path":"Assets/Scripts/Gameplay/Room2CodeValidator.cs","role":"Room 2's exit-code check against GameState.","source":"// @role Room 2's exit-code check against GameState.\n// @calls GameState\n\nusing UnityEngine;\n\n/// Room 2's exit keypad checks guesses against this instead of CodeManager/Room 1's code.\npublic class Room2CodeValidator : MonoBehaviour, IKeypadValidator\n{\n    public bool Validate(int[] guess)\n    {\n        if (guess == null || guess.Length != 4) return false;\n        for (int i = 0; i < 4; i++)\n            if (guess[i] != GameState.Room2Code[i]) return false;\n        return true;\n    }\n}\n"},"RoomEntryTrigger":{"path":"Assets/Scripts/Gameplay/RoomEntryTrigger.cs","role":"First-entry doorway trigger — starts the room timer, sets the save checkpoint, shows the objective toast.","source":"// @role First-entry doorway trigger — starts the room timer, sets the save checkpoint, shows the objective toast.\n// @calls GameState, RoomTimer, ObjectiveToast, Inventory\n\nusing UnityEngine;\n\n/// Sits in a room's entrance doorway. The player's FIRST pass through it: records a save\n/// checkpoint (this room + current inventory), starts that room's RoomTimer (if it has one), and\n/// shows the room's objective toast. Leaving and re-entering does nothing further — per spec,\n/// leaving a room never pauses its timer, and the checkpoint is only ever the most recent\n/// *first* entry, not refreshed on every lap through the doorway.\n[RequireComponent(typeof(Collider))]\npublic class RoomEntryTrigger : MonoBehaviour\n{\n    [Tooltip(\"1-4. Rooms without a number (Start, F, the exit corridor) just pass 0 and skip the checkpoint.\")]\n    public int roomNumber;\n    public RoomTimer timer; // null for rooms with no countdown (F, the exit corridor)\n    [TextArea] public string objectiveText;\n\n    bool _entered;\n\n    void Reset()\n    {\n        GetComponent<Collider>().isTrigger = true;\n    }\n\n    void OnTriggerEnter(Collider other)\n    {\n        if (_entered || !other.CompareTag(\"Player\")) return;\n        _entered = true;\n\n        if (roomNumber > 0)\n            GameState.SetCheckpoint(roomNumber, Inventory.Instance != null ? Inventory.Instance.SnapshotIds() : new System.Collections.Generic.List<string>());\n\n        timer?.BeginCountdown();\n\n        if (!string.IsNullOrEmpty(objectiveText) && ObjectiveToast.Instance != null)\n            ObjectiveToast.Instance.Show(objectiveText);\n    }\n}\n"},"RoomExitTrigger":{"path":"Assets/Scripts/Gameplay/RoomExitTrigger.cs","role":"Marks a room solved on exit; the final one ends the game in victory.","source":"// @role Marks a room solved on exit; the final one ends the game in victory.\n// @calls GameState\n\nusing UnityEngine;\nusing UnityEngine.SceneManagement;\n\n/// Sits just past a room's (now open) exit door. Walking into it marks that room solved in\n/// GameState. Only the final exit corridor's trigger (isFinalExit = true) actually ends the game;\n/// every other room's trigger just lets the player continue toward the next one — per the new\n/// flow, Room 1's own door no longer wins the game by itself.\n[RequireComponent(typeof(Collider))]\npublic class RoomExitTrigger : MonoBehaviour\n{\n    [Tooltip(\"1-4, which room this trigger sits behind.\")]\n    public int roomNumber;\n    [Tooltip(\"True only for the trigger at the end of the exit corridor, after Room 4.\")]\n    public bool isFinalExit;\n\n    void Reset()\n    {\n        GetComponent<Collider>().isTrigger = true;\n    }\n\n    void OnTriggerEnter(Collider other)\n    {\n        if (!other.CompareTag(\"Player\")) return;\n        GameState.MarkRoomSolved(roomNumber);\n\n        if (isFinalExit)\n        {\n            GameState.WinGame();\n            SceneManager.LoadScene(\"End\");\n        }\n    }\n}\n"},"RoomTimer":{"path":"Assets/Scripts/Gameplay/RoomTimer.cs","role":"Per-room silent countdown — flicker, sequential light shutoff, blackout loss.","source":"// @role Per-room silent countdown — flicker, sequential light shutoff, blackout loss.\n// @calls GameState, LightSwitchClue\n// @tune totalDuration:float:60-400:room time limit (s)\n// @tune flickerWindow:float:20-90:seconds remaining when flicker starts\n// @tune shutoffWindow:float:5-40:seconds remaining when sequential shutoff starts\n// @tune blackoutHold:float:1-5:blackout hold before loss (s)\n// @tune penaltyFlashDuration:float:0.1-1:penalty dim-flash length (s)\n\nusing System.Collections;\nusing System.Collections.Generic;\nusing System.Linq;\nusing UnityEngine;\nusing UnityEngine.SceneManagement;\n\n/// Per-room silent countdown, generalized from the original Room-1-only LightsOutTimer so it can\n/// be dropped onto any of the four challenge rooms. Only affects this room's own ceiling lights:\n/// lights flicker with increasing frequency in the last `flickerWindow` seconds, then shut off one\n/// by one over the last `shutoffWindow` seconds, then a full blackout holds for `blackoutHold`\n/// before the player loses. No countdown number is ever shown — the lights themselves are the\n/// clock. Does NOT start on its own; call BeginCountdown() once the player actually enters the\n/// room (a RoomEntryTrigger normally does this).\npublic class RoomTimer : MonoBehaviour\n{\n    [Tooltip(\"1-4. Used for GameState.Fail() so the End screen can report which room ran out of time.\")]\n    public int roomNumber;\n\n    public bool timerEnabled = true;\n    public float totalDuration = 180f;\n    public float flickerWindow = 60f;  // starts flickering when this many seconds remain\n    public float shutoffWindow = 20f;  // starts sequential shutoff when this many seconds remain\n    public float blackoutHold = 2f;\n    [Tooltip(\"How long a Penalty() dims the room's lights as feedback.\")]\n    public float penaltyFlashDuration = 0.3f;\n\n    [Tooltip(\"Every ceiling light in this room, auto-populated by the generator.\")]\n    public Light[] roomLights = System.Array.Empty<Light>();\n    [Tooltip(\"Same order as roomLights: each light's emissive ceiling panel.\")]\n    public Renderer[] roomPanels = System.Array.Empty<Renderer>();\n\n    [Tooltip(\"Room 1 only: the specific light the Bar clue's switch controls, so it can be force-revealed if the timer kills it first.\")]\n    public Light linkedLight;\n    public LightSwitchClue linkedSwitchClue;\n\n    public bool HasExpired => timerEnabled && _elapsed >= totalDuration;\n    public bool IsRunning => _started && !_blackoutStarted;\n\n    bool _started;\n    float _elapsed;\n    bool _flickerStarted, _shutoffStarted, _blackoutStarted;\n    readonly HashSet<Light> _off = new HashSet<Light>();\n    List<Light> _shutoffOrder;\n    Dictionary<Light, Material> _panelInstances;\n    Dictionary<Light, Color> _panelBaseEmission;\n\n    public void BeginCountdown()\n    {\n        if (_started || !timerEnabled) return;\n        _started = true;\n\n        _shutoffOrder = roomLights.OrderBy(_ => Random.value).ToList();\n        _panelInstances = new Dictionary<Light, Material>();\n        _panelBaseEmission = new Dictionary<Light, Color>();\n        for (int i = 0; i < roomLights.Length && i < roomPanels.Length; i++)\n        {\n            if (roomLights[i] == null || roomPanels[i] == null) continue;\n            Material mat = roomPanels[i].material;\n            _panelInstances[roomLights[i]] = mat;\n            _panelBaseEmission[roomLights[i]] = mat.GetColor(\"_EmissionColor\");\n        }\n    }\n\n    /// Docks `seconds` off the remaining time (used for wrong-guess penalties) and gives a brief\n    /// visual flash so the player feels it even though no number is ever shown.\n    public void Penalty(float seconds)\n    {\n        if (!_started || _blackoutStarted) return;\n        _elapsed += seconds;\n        StartCoroutine(PenaltyFlash());\n    }\n\n    IEnumerator PenaltyFlash()\n    {\n        foreach (var kv in _panelInstances)\n        {\n            if (_off.Contains(kv.Key)) continue;\n            kv.Value.SetColor(\"_EmissionColor\", _panelBaseEmission[kv.Key] * 0.15f);\n        }\n        yield return new WaitForSeconds(penaltyFlashDuration);\n        foreach (var kv in _panelInstances)\n        {\n            if (_off.Contains(kv.Key)) continue;\n            kv.Value.SetColor(\"_EmissionColor\", _panelBaseEmission[kv.Key]);\n        }\n    }\n\n    void Update()\n    {\n        if (!_started || !timerEnabled || _blackoutStarted) return;\n\n        _elapsed += Time.deltaTime;\n        float remaining = totalDuration - _elapsed;\n\n        if (remaining <= 0f)\n        {\n            _blackoutStarted = true;\n            StartCoroutine(Blackout());\n            return;\n        }\n\n        if (remaining <= flickerWindow && !_flickerStarted)\n        {\n            _flickerStarted = true;\n            StartCoroutine(FlickerLoop());\n        }\n\n        if (remaining <= shutoffWindow && !_shutoffStarted)\n        {\n            _shutoffStarted = true;\n            StartCoroutine(ShutoffSequence());\n        }\n    }\n\n    IEnumerator FlickerLoop()\n    {\n        while (!_shutoffStarted && !_blackoutStarted)\n        {\n            float remaining = totalDuration - _elapsed;\n            // Delay between random blinks shrinks from ~1.2s down to ~0.15s as the flicker\n            // window runs out, so flickering visibly speeds up toward the shutoff phase.\n            float progress = Mathf.InverseLerp(flickerWindow, shutoffWindow, Mathf.Max(remaining, shutoffWindow));\n            float delay = Mathf.Lerp(1.2f, 0.15f, progress);\n            yield return new WaitForSeconds(delay);\n\n            if (roomLights.Length == 0) continue;\n            Light l = roomLights[Random.Range(0, roomLights.Length)];\n            if (l == null || _off.Contains(l)) continue;\n            StartCoroutine(QuickBlink(l));\n        }\n    }\n\n    IEnumerator QuickBlink(Light l)\n    {\n        l.enabled = false;\n        yield return new WaitForSeconds(0.08f);\n        if (!_off.Contains(l)) l.enabled = true;\n    }\n\n    IEnumerator ShutoffSequence()\n    {\n        if (_shutoffOrder.Count == 0) yield break;\n        float interval = shutoffWindow / _shutoffOrder.Count;\n        foreach (Light l in _shutoffOrder)\n        {\n            if (l == null) continue;\n            TurnOff(l);\n            yield return new WaitForSeconds(interval);\n        }\n    }\n\n    void TurnOff(Light l)\n    {\n        if (_off.Contains(l)) return;\n        _off.Add(l);\n        l.enabled = false;\n        if (_panelInstances.TryGetValue(l, out Material mat))\n            mat.SetColor(\"_EmissionColor\", Color.black);\n\n        if (l == linkedLight && linkedSwitchClue != null)\n            linkedSwitchClue.ForceReveal();\n    }\n\n    IEnumerator Blackout()\n    {\n        foreach (Light l in roomLights)\n            if (l != null) TurnOff(l);\n\n        yield return new WaitForSeconds(blackoutHold);\n\n        GameState.Fail(roomNumber);\n        SceneManager.LoadScene(\"End\");\n    }\n}\n"},"SlideMover":{"path":"Assets/Scripts/Gameplay/SlideMover.cs","role":"Generic smooth local-position slide, reused by doors/drawers/cabinets.","source":"// @role Generic smooth local-position slide, reused by doors/drawers/cabinets.\n\nusing System;\nusing System.Collections;\nusing UnityEngine;\n\n/// Generic \"smoothly slide this transform's local position to a target over N seconds\" helper,\n/// reused by the cabinet, the drawer front, and the exit door.\npublic class SlideMover : MonoBehaviour\n{\n    Coroutine _running;\n\n    public void SlideTo(Vector3 targetLocalPosition, float duration, Action onComplete = null)\n    {\n        if (_running != null) StopCoroutine(_running);\n        _running = StartCoroutine(Co(targetLocalPosition, duration, onComplete));\n    }\n\n    IEnumerator Co(Vector3 target, float duration, Action onComplete)\n    {\n        Vector3 start = transform.localPosition;\n        float t = 0f;\n        while (t < duration)\n        {\n            t += Time.deltaTime;\n            float k = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(t / duration));\n            transform.localPosition = Vector3.Lerp(start, target, k);\n            yield return null;\n        }\n        transform.localPosition = target;\n        onComplete?.Invoke();\n    }\n}\n"},"StoolCarrier":{"path":"Assets/Scripts/Gameplay/StoolCarrier.cs","role":"Room 2 — carries/places the stool with a ghost placement preview.","source":"// @role Room 2 — carries/places the stool with a ghost placement preview.\n// @calls FirstPersonController\n// @tune maxPlaceDistance:float:1-4:how far from the player the stool can be placed (m)\n\nusing UnityEngine;\n\n/// Carries the Room 2 stool: E on it picks it up (hides the real stool, shows a semi-transparent\n/// preview that follows the camera's aim point), E again while carrying tries to place it there.\n/// Placement is only valid inside this room, within `maxPlaceDistance`, and on a roughly flat,\n/// unobstructed surface. PlayerInteractor routes E to TryPlace() first whenever IsCarrying is\n/// true, before any normal raycast interaction, matching \"看向地面按 E 放下\" taking priority over\n/// whatever else the player might be looking at while holding it.\npublic class StoolCarrier : MonoBehaviour\n{\n    public static StoolCarrier Instance { get; private set; }\n\n    public GameObject stoolVisual;   // the real, physically-collidable stool in the world\n    public Transform ghostPreview;   // semi-transparent copy, shown only while carrying\n    public Renderer ghostRenderer;\n    public Bounds roomFloorBounds;   // Room 2's floor footprint in world space (XZ matters; Y ignored)\n    public float maxPlaceDistance = 2f;\n    [Tooltip(\"Stool's own pivot-to-base offset (half its height, since a primitive cube's pivot is its center). Added on top of the raycast floor hit so the stool rests ON the floor instead of sinking into it by half its height.\")]\n    public float restingPivotOffset = 0.225f;\n    public Color validColor = new Color(0.3f, 0.9f, 0.4f, 0.4f);\n    public Color invalidColor = new Color(0.9f, 0.3f, 0.3f, 0.4f);\n\n    public bool IsCarrying { get; private set; }\n    /// Set true (via OnTriggerStay) by any DoorwayStoolBlock the player is overlapping this frame\n    /// while carrying; PlayerInteractor reads it to show \"Put the stool down first\" ahead of any\n    /// other prompt. Cleared every frame in LateUpdate so it only reflects \"right now\".\n    public bool NearBlockedDoor;\n\n    bool _placementValid;\n    Vector3 _pendingPlacePos;\n    Camera _cam;\n\n    void Awake() => Instance = this;\n\n    void Start()\n    {\n        _cam = FirstPersonController.Instance != null ? FirstPersonController.Instance.Camera : null;\n        if (ghostPreview != null) ghostPreview.gameObject.SetActive(false);\n    }\n\n    public void PickUp()\n    {\n        if (IsCarrying) return;\n        IsCarrying = true;\n        if (stoolVisual != null) stoolVisual.SetActive(false);\n        if (ghostPreview != null) ghostPreview.gameObject.SetActive(true);\n    }\n\n    public bool TryPlace()\n    {\n        if (!IsCarrying) return false;\n        if (!_placementValid) return false;\n\n        IsCarrying = false;\n        if (stoolVisual != null)\n        {\n            stoolVisual.transform.position = _pendingPlacePos + Vector3.up * restingPivotOffset;\n            stoolVisual.SetActive(true);\n        }\n        if (ghostPreview != null) ghostPreview.gameObject.SetActive(false);\n        return true;\n    }\n\n    void Update()\n    {\n        if (!IsCarrying || _cam == null || ghostPreview == null) return;\n\n        Ray ray = new Ray(_cam.transform.position, _cam.transform.forward);\n        bool hit = Physics.Raycast(ray, out RaycastHit info, maxPlaceDistance + 1f, ~0, QueryTriggerInteraction.Ignore);\n\n        if (hit)\n        {\n            bool flatEnough = Vector3.Angle(info.normal, Vector3.up) < 15f;\n            bool closeEnough = info.distance <= maxPlaceDistance;\n            bool inRoom = roomFloorBounds.Contains(new Vector3(info.point.x, roomFloorBounds.center.y, info.point.z));\n            _placementValid = flatEnough && closeEnough && inRoom;\n            _pendingPlacePos = info.point;\n            ghostPreview.position = info.point + Vector3.up * restingPivotOffset;\n        }\n        else\n        {\n            _placementValid = false;\n        }\n\n        if (ghostRenderer != null)\n            ghostRenderer.material.color = _placementValid ? validColor : invalidColor;\n    }\n\n    void LateUpdate() => NearBlockedDoor = false;\n}\n"},"StoolPickupTarget":{"path":"Assets/Scripts/Gameplay/StoolPickupTarget.cs","role":"Room 2 stool's pickup trigger.","source":"// @role Room 2 stool's pickup trigger.\n// @calls StoolCarrier\n\nusing UnityEngine;\n\n/// Lives on the physical stool object. E picks it up via the room's StoolCarrier. Once carrying,\n/// this object is inactive (StoolCarrier hides it), so there's nothing to look at/re-trigger\n/// pickup on until it's placed down again.\npublic class StoolPickupTarget : MonoBehaviour, IInteractable\n{\n    public StoolCarrier carrier;\n\n    public string InteractionPrompt => \"Pick up stool\";\n    public bool CanInteract => carrier != null && !carrier.IsCarrying;\n    public string BlockedReason => null;\n\n    public void Interact(GameObject interactor) => carrier.PickUp();\n}\n"},"TitleMenu":{"path":"Assets/Scripts/Gameplay/TitleMenu.cs","role":"Title screen — Start begins a brand-new game.","source":"// @role Title screen — Start begins a brand-new game.\n// @calls GameState\n\nusing UnityEngine;\nusing UnityEngine.SceneManagement;\n\npublic class TitleMenu : MonoBehaviour\n{\n    void Start()\n    {\n        Cursor.lockState = CursorLockMode.None;\n        Cursor.visible = true;\n    }\n\n    public void OnStartPressed()\n    {\n        GameState.BeginNewGame();\n        SceneManager.LoadScene(\"WhiteBox_LastLight\");\n    }\n}\n"}}};
